(window.STORIES=window.STORIES||[]).push(...[{"n": 29, "l": "الجزء ٤٠ | سليمان ٢ | والجزء ٤١ | سليمان ٣____الهدهد", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الأربعون\n#قصة_سليمان_الجزء_الثاني\n#قصة_النملة_والريح\nكنا واقفين المرة إللي فاتت عند سليمان عليه السلام لما كان راجع من الجهاد وسمع صوت بيتكلم،\nكان إيه الصوت ده بقى\nكان صوت نملة بتنصح باقي قرية النمل إللي هي عايشة معاهم وبتقول لهم:\nكل النمل يجري على الجحور بسرعة، أحسن سليمان عليه السلام وجيشه يدوسوا علينا ويقتلونا وهمّ مش واخدين بالهم\n\"حَتَّى إِذَا أَتَوْا عَلَى وَادِي النَّمْلِ قَالَتْ نَمْلَةٌ يَا أَيُّهَا النَّمْلُ ادْخُلُوا مَسَاكِنَكُمْ لا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لا يَشْعُرُونَ\"\n☆احنا ممكن نشوف الجملة دي عادية جدا لكن الجملة دي فيها فوائد كتيرة وكنوز عظيمة \nمنها:\n♡ الفائدة الأولى:\nإن إللي اتكلمت \"نملة\"... مجرد نملة عادية مالهاش أي وزن ولا أي مكانة وبالعافية متشافة أصلا، ومع ذلك نصحت باقي قرية النمل عشان مصلحتهم..\nمقالتش مثلا طب وأنا مالي أنصحهم ليه؟ \nهو أنا يعني كلامي إللي هيأثر\nوأصلا لو نصحتُهم ماهمّ ممكن مايسمعوش كلامي عشان أنا مش معروفة ومجرد نملة بسيطة زي أي نملة\nوكمان فيه نمل تاني غيري شايفين جنود سليمان، ماهمّ إللي يتكلموا إشمعنى أنا؟\nمليش دعوة خليني ف حالي... وكمان فين دور الملكة والجنود؟\nمش المفروض إنهم همّ إللي ياخدوا بالهم من المخاطر دي\nأنا أروح أستخبى وأنقذ نفسي وخلاص وهمّ أكيد هيتصرفوا\nمقالتش أي حاجة من دي خالص.. هي مجرد ما شافت جيش سليمان عليه السلام جاي ناحيتهم، نصحت بكل قوتها وطاقتها وعملت إللي عليها\nوحتى لو باقي النمل ماسمعش كلام النملة فعلى الأقل شالت اللوم والذنب من عليها،\nيعني محدش هيقدر ييجي يقولها لو حصل لهم حاجة إنتِ محذرتيناش ليه؟\nولا هي هتلوم نفسها أو تندم وتقول ياريتني كنت نصحتهم\nفمهما كانت معلوماتك بسيطة.. مهما كنت شايف نفسك حاجة صغيرة .. مهما شفت الناس مش هتسمع كلامك وإنك مهما قلت ونصحت مفيش فايدة لإنك شايف إن جهدك متواضع وبسيط مالوش وزن ومش متشاف:\nاعمل إللي عليك دايما بدون تقصير، وانصح لله قدر وسعك وأجرك على الله بقدر طاقتك.. حتى حديث رسول الله ﷺ  بيقول إيه؟\nبيقول : بلغوا عني ولو《 أية》\n♡الفائدة الثانية: حُسن الظن\nسليمان عليه السلام كان معروف إنه نبي، \nوبالذات الدواب والحشرات والطيور تعرفه بشكل خاص لإن ربنا رزقه معجزة إنه يفهم لغتهم ويتخاطب معاهم بيها، وعارفين إن سليمان أخلاقه عظيمة، فطبيعي إن إللي عنده أخلاق ميطلعش منه القسوة أو الأذية لغيره،\nفسليمان وجيشه مش هيقتلوا النمل في طريقهم كده بدون سبب، يعني لو حصل وقتلوهم فهيكون بدون قصد غير متعمدين\nمثال من واقعنا: لما يكون في حياتك شخص متعرفش عنه إلا كل خير، وحصل منه موقف زعلك، وفي الطبيعي إنه ميطلعش منه الموقف ده،\nفالمفروض إنك تقول أكيد هو عمل كده وهو مايعرفش، أو عمله بدون قصد ، أو عمله مضطر، \nأو يمكن قصده بالفعل ده كذا مش كذا، أو أكيد وراه سبب منطقي ومعتبر مش زي ما أنا فاهم أو...أو...\nعارفين أقرب حاجة للموضوع ده إيه وواضحة أوي كمثال؟\nموضوع الشيوخ والعلماء. \nالشيوخ والعلماء《المُعتبرين》طبعا، مش أي شيوخ..\nالطبيعي إنهم معروف عنهم من ظاهرهم إنهم ناس بتتقي الله وبتعلّم الناس الخير من سنين،\nفلما يوصلني كلام عن إن حد من العلماء دول إنه عمل حاجة مخالفة للي نعرفه عنه من الخير، المفروض نعمل زي نملة سليمان عليه السلام ونقول: أكيد مكنش يقصد... أكيد الكلام اتنقل عنه غلط... أكيد كان عنده عذره....... \nأيا كان\nطيب ولو طلع الكلام صح وإن فعلا الشيخ اللي أنا أحسنت الظن بيه كان متعمد للخطأ وسيئ النية و...و...؟ \nيبقى أنا مخسرتش أي حاجة نهائي، بل العكس ربنا يأجرني على حسن ظني\nوهصحح للناس الكلام وأفهمهم إن ده كان حسن ظن مني فيه إللي ربنا أمرني بيه، لكن بعد ما اتضح\n《بالدليل الواضح الصريح إللي ميحتملش تخمين》 إن حسن ظني مش في محله، فأنا بتراجع عن ده،\nفي حين إنه لو طلع بريء وأنا كنت أسأت الظن بيه واتكلمت عليه بأي سوء...؟ فأكييييد أنا الخسران\nفالمهم إن الأصل هو إحسان الظن، وعشان كده ربنا عز وجل قال:\n\"اجتبنوا كثيرا من الظن.. إن بعض الظن إثم\"\n◇خلونا نشوف مثال حصل أيام النبي ﷺ \nعارفين حادثة الإفك ؟\nلما اتُّهمت السيدة عائشة رضي الله عنها في عرضها بالظلم والبهتان، والناس بدأت تتكلم عنها بسوء وهي المُبرأة الشريفة إللي محدش عرف عنها أي سوء... \nوصل الكلام لواحد من الصحابة اسمه أبو أيوب الأنصاري وزوجته ،\nفزوجته بتقول له :\nسمعت الكلام إللي بيتقال على عائشة وصفوان\nقال لها :سمعت... فقالت له : وانت إيه رأيك \n؟! \nفقال لها: لو انتِ كنتِ مكان عائشة كنتِ هتعملي الفاحشة دي؟\nفقالت له: لأ\nقال لها: طب لو أنا كنت مكان صفوان تعرفي عني إني ممكن كنت أعمل الفاحشة دي؟\nقالت له : لأ\nقام قايل لها: فعائشة أحسن منكِ، وصفوان أحسن مني\nبس كده وانتهت القضية من الأساس بحسن ظن عظيم \nفلما نزلت آيات البراءة، تعتقدوا مين إللي كان خسران؟\nأبو أيوب الانصاري وزوجته إللي أحسنوا الظن وحفظوا لسانهم؟ \nولّا الناس إللي اتكلمت في عرض السيدة عائشة البريئة\nنرجع بقى للنملة ونشوف رد فعل سليمان عليه السلام على كلامها كان إيه،\nلما سليمان عليه السلام سمع كلام النملة الضعيفة إللي يادوب باينة من الأرض تبسم ضاحكا من قولها، ابتسم وهو سعيد ولم يغضب من كلامها ومقالش مثلا:\n إزاي نملة تقول اسمي كده بدون أي ألقاب وأنا ملك الأرض\nبالعكس، ده استشعر مدى عظمة النعمة إللي هو فيها، وحس بخضوع وخشوع وتواضع لجلال الله ورزقه وكرمه معاه وفضله،\nودعا ربنا إنه يلهمه حسن شكر النعم إللي أنعم بيها عليه وعلى أبويه، دي بالعمل الصالح والعبادات،\nأنعم عليه بالملك...وأنعم عليه بإنه علمه لغة المخلوقات، فلو مكنش يعرف لغتهم مكنش فهم كلام النملة\n\"فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ \"\n◇سليمان عليه السلام كان مَلِك شديد الثراء واسع المُلك أه،  لكنه كان متواضع لربه وخافض الجناح لخلقه، مش متكبر بنعم ربنا عليه،\nودي من أخلاق المؤمنين...إنهم ينسبوا كل فضل ونعمة لله ويلزموا شكره على النعم دي باللسان وباستعمالها في مرضاته عز وجل ،\nوخدوا بالكم إللي بينسى شكر نِعم ربنا عليه في الدنيا ربنا بينساه في الآخرة\n☆هو ربنا بينسى\nكلمة النسيان لها معنيين:\nمعنى النسيان بتاعنا إللي هو إني ما افتكرش حاجة معينة: أنسى أصلي /أنسى إني صايم وأشرب/ أنسى إني اتوضيت/ وهكذا،\nوطبعا ده من صفات النقص ، لا يتصف بها أبدا ربنا عز وجل\nالمعنى الثاني: وهو بمعنى التّرك... يعني إني أسيب الشيء ده ولا أبالي بشأنه،\nيعني ربنا بيقول: \"نَسُوا الله فَنَسِيَهم\"\nنسوا الله هنا معناها إن الناس تركوا العمل بأوامر ربنا، فيوم القيامة ربنا هيتركهم في النار\nوربنا يوم القيامة هيقول للعبد:\n مش أنا زوِّجتك؟ مش أنا سخّرت لك الدواب والكون ده كله؟ ويعدّد نعمه على عبده ويسأله عن شكر النعم دي كلها ويحاسبه هل كان موقن إنه هيقابل ربنا للجزاء ولّا لأ،\nفالعبد هيقول : \nيارب نسيت، فربنا هيقول له : إحنا كمان هننساك... بمعنى \"هنَتَنَاسَاك\".. يعني زي ما انت تركت شكر النعم والطاعة وانت متعمد وعارف إنك راجع لربك في يوم من الأيام، ربك كمان هيتركك في النار\nلأن لو العبد  هنا \"ناسي\" بمعنى  إنه مش فاكر، مكنش ربنا هيعاقبه، لإن الناسي مرفوع عنه الحساب والقلم لحد ما يتذكر، زي ما قال رسول الله ﷺ : \n\"رُفِعَ عن أُمَّتي الخطأ، والنسيان، وما استكرهوا عليه\"\nالمهم يعني إن سليمان عليه السلام كان دائم الشكر لله مع الدعاء لنفسه ولأبويه؛ لإن من أخلاق المؤمنين كمان إنهم\nيدعوا لأبائهم كل ما يدعوا لأنفسهم لأن أباؤهم سبب في وجودهم في الدنيا بعد إذن الله ومشيئته،\nوبالتالي سبب في كل نعيم هما حاصلين عليه بحول الله وقوته\nاحنا عارفين من المرة إللي فاتت إن مُلك سليمان أعظم مُلك لحد قيام الساعة، وإن ربنا سخّر له الطير والجن،\nومن الحاجات إللي ربنا سخرها كمان لسليمان عليه السلام: \"الريح\"\nوتسخير الريح لسليمان كان له قصة ،\nوهي إن في يوم من الأيام ، كان سليمان عليه السلام بيستعرض خيول الصّافِنات، والصافنات دي هي أفضل أنواع الخيول ، \nهي إللي بتقف على ٣ أرجل فقط، وعند الرجل الرابعة بتقف على طرفها، يعني بتقف على ثلاثة أرجل وطرف حافر\n\"إِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ الْجِيَاد\"\nوسليمان عليه السلام كان بيحب الجهاد في سبيل الله جدا، عشان ينشر دين التوحيد لله رب العالمين في الأرض، \nفكان بيستعمل الخيل دي في الجهاد،\nففي اليوم ده عرض جنوده الخيل دي عليه زي استعراض عسكري كده \nفضل يتابعهم ويتفرج على جمالهم وهو منبهر ببديع صنع الله وجمال النعمة إللي بين إيديه من وقت الظهر لحد ما الشمس غابت، وهو مش واخد باله خالص من الوقت؛\nلإن عرض الخيول واختبار مهاراتها وتدريبها بياخد وقت، \nفلما غربت الشمس انتبه سليمان عليه السلام إنه عدى وقت الذكر بتاعه،\nوالذكر هنا ممكن يكون ذكر الله المعروف باللسان زي مثلا يعني أذكار المساء، أو الذكر بمعنى الصلاة يعني صلاة العصر، على خلاف في التفاسير...\nزي مثلا لما بيكون عندك ضغط في الكلية أو امتحانات أو زيارة مهمة عندك في البيت هتم، واتلهيت فيهم لحد ما نسيت الصلاة أو الأذكار أو مشوار مهم حتى، أهه ده إللي حصل مع سليمان عليه السلام،\n\"فَقَالَ إِنِّي أَحْبَبْتُ حُبَّ الْخَيْرِ عَنْ ذِكْرِ رَبِّي حَتَّى تَوَارَتْ بِالْحِجَابِ\"\nومع ذلك سليمان عليه السلام مقالش خلاص بقى، ماهو ربنا غفور رحيم وده كان غصب عني وما أخدتش بالي وراح عَدَّى الموضوع ببساطة كده زي ماحنا بنعمل للأسف في أوقات كثيرة، لأ...\nده قال لجنوده رجّعوا لي الخيل تاني، فلما رجّعوها نزل عليها بالسيف يضرب السيقان والأعناق لحد ما قتل الخيل كلهم\n\"رُدوهَا عَلَيَّ فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ\"\n☆طيب والخيل ذنبها إيه\n مش هو إللي نسي\nخلينا نقرب المعنى،\nمثلا لما أنسى صلاة أو انام عن صلاة، مش أنا بشوف إيه السبب إللي خلاني أنسى أو السبب إللي خلاني أنام عن الصلاة دي؟\nيعني لو واحد بيسهر على موبايله وبيضيع وقته وييجي ينام قبل الفجر بساعة وميصليش الفجر، ده المفروض يعمل إيه؟ المفروض يعاقب نفسه في الموبايل ده تاني يوم عشان يؤدب نفسه ويبطل سهر عشان يعرف يصحى لصلاة الفجر،\nيعني مفروض يتخلص من الحاجة إللي بسببها وقع في المعصية..\nوده إللي حصل مع سليمان عليه السلام، هو كان بيحب الخيل جدا، فحبه لها وطول متابعته ليها ولجمال وقفتها ورشاقتها ولياقتها خلاه ينسى ذكر الله سواء كانت صلاة العصر أو الذكر العادي زي ما قلنا، \nفقام اتخلص منها، عشان يُؤدب نفسه ويعلمها إن المرة الجاية إللي هتنسى فيها حق الله عز وجل بسبب أمر دنيوي هي بتحبه، هيتخلص منه إرضاءًا لله عشان تتعلم متكررش الموضوع ده تاني معاه..\nولو تاخدوا بالكم لفظة القرآن\n\"فقطفق مسحًا بالسوقِ والأعناق\"\nوكأن سليمان عليه السلام بيضاعف تأديب نفسه بضرب مكان إعجابه بالصافنات، وإللي هو طريقة وقفتها الرشيقة ولياقتها، فمش مجرد قتل وقطع للعنق، \nده قطع للسيقان دي كمان إللي فتنته عن حق الله عز وجل، والله أعلم.\nوطبعا أكيد كان متألم وهو بيقتلها، وكل ما كان الألم شديد على النفس كل ما كان الدرس إللي بنتعلمه راااسخ في القلب، فكل مرة هيشوف خيل هيفتكر حق الله في الذكر، وإنه ماينساش تاني\n☆وهنا ملحوظة مهمة:\nسليمان عليه السلام كان بيحب الجهاد إللي هو من أعظم العبادات إللي ممكن نتقرب بها لربنا، \nومع ذلك دخل لسليمان غير ما يحس حب أمر دنيوي بشكل ألهاه عن حق الآخرة ولو لحظات بسيطة،\nفكان الرد منه هو ذبح الدنيا\nواحنا كمان ممكن نقع في الفخ ده، يعني ممكن نبدأ عمل بنية لله، ويكون فعلا طاعة لله لكن مع الوقت تتحول الطاعة دي لفتنة عن الطاعة، إزاي\nزي مثلا فكرة عمل عزومات في رمضان للأسرة كلها،\nبيكون فيها ثواب إطعام الطعام وصلة رحم وكمان إفطار صائمين، دي طاعة أهه، فتتحول بقى لفتنة عن الطاعة لما نقعد نتفنن في أصناف الطعام والمُقبلات والتسالي والسمر والسهر، \nوفجأة يبقى أقل قدر فيها هو بس إللي بقى من نصيب الآخرة بعد ما كانت البداية أصلا كلها من نصيب الآخرة، وشوية شوية لو الإنسان منتبهش كده زي سليمان عليه السلام، بتتحول وتبقى سبب للمعصية كمان،\nيعني يبقى في اختلاط بعد ما كنا بنفصل الرجال عن النساء، والعزومة تحولت لسهر للساعة 12 بالليل مع بعض قدام الفقرات الرمضانية للأسف، \nوكل ده يأثر على صلاة التراويح والفجر و قراءة القرآن في شهر القرآن.\nفناخد بالنا، والحاجة إللي نلاقيها بدأت تشغلنا عن حقوق الله وحقوق العباد، نتركها لله أو نأدب نفسنا فيها بالشكل إللي يعصمنا من الإفتتان بيها.\n◇طيب برده ما هو سليمان قتل حيوان بريء ملوش ذنب\nماهو أصلا قتل الحيوانات جائز وخصوصا إنها لو كانت حيوانات بتؤكل \nزي مثلا لو واحدة عندها طيور فوق السطح بتربيهم فانشغلت بيهم عن الصلاة، فراحت جابت الطيور دي كلها\nوذبحتها وتصدقت بيهم عشان متشغلهاش تاني عن الصلاة عادي جدا\nفسليمان عليه السلام لما قتل الخيل استغلها برده، مش إنه قتلها ورماها هَدر كده،\n لأ، ده وزعها كإطعام، وكان في شريعتهم إن الخيل أكله مباح، وفي شريعتنا برده أكل الخيل مُباح عادي.\n♤ملحوظة:\n التفسير إللي قلناه عن الآية:\n\"رُدوهَا عَلَيَّ فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ\"\nهو تفسير الإمام ابن كثير، وهو أصح الأقوال وأقربها للمنطق، لأن في أقوال تانية ممكن تسمعوها أو تقرأوها.\nفلما سليمان عليه السلام ترك الخيل لله ربنا عوضه عنها بنعمة أعظم منها .. عوضه عز وجل بنعمة تسخير الريح، يعني سخّر له الريح تكون تحت أمره تنقله هو وجنوده من مكان لمكان، والريح طبعا أسرع من الخيل، ومن ترك شيئا لله عوضه خيرا منه \n\"فَسَخَّرْنَا لَهُ الرِّيحَ تَجْرِي بِأَمْرِهِ رُخَاءً حَيْثُ أَصَابَ\"\nفي يوم تاني كان سليمان عليه السلام بيتفقد الجيوش بتاعته، وكان عنده جيش من الإنس وجيش من الجن وجيش من الطير زي ما قلنا المرة إللي فاتت،\nففي يوم من الأيام بيتابع فيها جيوشه، لما وصل لجيش الطيور ملقاش الهدهد! \nواستغرب هو راح فين المفروض يكون هنا في مكانه؟!\nفقرر إنه هيعذبه عذاب شديد أو هيذبحه ، إلا لو كان الهدهد عنده سبب مقنع لغيابه عني كده بدون إذن\n\"وتَفَقَّدَ الطَّيْرَ فَقَالَ مَا لِيَ لا أَرَى الْهُدْهُدَ أَمْ كَانَ مِنَ الْغَائِبِينَ ۩  لأُعَذِّبَنَّهُ عَذَابًا شَدِيدًا أَوْ لَأَذْبَحَنَّهُ أَوْ لَيَأْتِيَنِّي بِسُلْطَانٍ مُّبِينٍ\"\nليه الهدهد كان غايب عن باقي الجيش؟\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء\n#الحلقة_الواحدة_والأربعون\n#قصة_سليمان_الجزء_الثالث\n#قصة_الهدهد\nاتكلمنا المرة إللي فاتت عن سليمان عليه السلام لما كان بيتفقّد الجيش بتاعه وملقاش طائر الهدهد موجود فتوعّد الهدهد إنه هيعذبه عذاب شديد لما يرجع\n\"وتَفَقَّدَ الطَّيْرَ فَقَالَ مَا لِيَ لا أَرَى الْهُدْهُدَ أَمْ كَانَ مِنَ الْغَائِبِينَ\"\n☆حد ممكن يسأل: \nهو كده سليمان عليه السلام مش قاسي شوية مع الحيوانات\nسليمان عليه السلام نبي وفي نفس الوقت مَلِك، يعني بإيده الأمر والنهي حتى على الحيوانات وبيعمل إللي بيشوفه مناسب كقائد للشعب والجيوش،\nوالهدهد جندي من جنود سليمان في جيش الطيور، فإزاي الجندي يغيب عن قائده من غير استئذان\nلكن سليمان عليه السلام كان عادل، فقال إن الهدهد لو جاب سبب مقنع خلاه يغيب عن الجيش هسامحه،\n\"لَأُعَذِّبَنَّهُ عَذَابًا شَدِيدًا أَوْ لَأَذْبَحَنَّهُ أَوْ لَيَأْتِيَنِّي بِسُلْطَانٍ مُّبِينٍ\"\nيعني سليمان عليه السلام مقالش إنه هيعذبه لغرض التعذيب ، لأ.. بمجرد إن يبقى في عذر مقبول، يبقى خلاص مفيش عقوبة\nبعد فترة بسيطة إلّا وسواد نازل من السماء وداخل على سليمان وسط الجنود من الجن والإنس والطيور والكل مُترقب يا ترى هيحصل إيه للهدهد \nفتكلم الهدهد وقال لسليمان عليه السلام:\nأنا عرفت معلومات انت متعرفهاش وجايبلكم أخبار غريبة ومافيشهاش أي شك أو إشاعات،\nمع إني هدهد صغير ضعيف، وإنت نبي وملك وعندك كل الجنود دي فأنا عندي معلومات خَفِيَت عنك\n\"فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِ وَجِئْتُكَ مِن سَبَإٍ بِنَبَإٍ يَقِينٍ\"\nأنا كنت في مملكة سبأ، وهناك لقيت الحاكم إللي بيحكم المملكة امرأة مش رجل، وهي غنية جدا وعندها من أسباب القوة والمُلك، وكرسي العرش بتاعها عظيم جدا،\n\"إِنِّي وَجَدتُّ امْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَيْءٍ وَلَهَا عَرْشٌ عَظِيمٌ\"\n☆ طيب ياهدهد انت مالك يعني تحكمهم امرأة ولّا رجل هتفرق إيه\nالهدهد استنكر وجود امرأة في الحكم لأن ده مش مكان النساء، \nربنا خلق المرأة بطبيعة وتكوين مختلف عن الرجل عشان هي لها دور في الحياة مختلف عن دور الرجل،\nالمرأة رقيقة وعاطفية وحنونة ومشاعرها دي بتغلب عليها أكتر من عقلها، \nعشان هو ده إللي هتحتاجه لما تيجي تقوم بدورها وهو تربية أبنائها ومراعاتهم ومراعاة تقلّباتهم في كل مراحل حياتهم وحُسن احتواءهم في المراحل دي كلها، \nودي حاجة معروفة من قديم الزمان ومسمعناش من أول آدم عليه السلام إن فيه امرأة حكمت بلد فيه رجال قبل ملكة سبأ،\nوكذلك النبوة مبتكونش غير في الرجال، لإن كل دي مهام بتحتاج قوة في البدن وقوة تحمل للصعاب وتغليب للعقل على العواطف واجتماع بباقي الرجال وقيادة الجيوش وطلب الرزق في الحر والبر، \nإلى آخر الأمور إللي ربنا خلق الرجل بطبيعته دي عشان يكون مُهيأ ليها أكتر من المرأة،\nوحتى في شريعة الإسلام، المرأة لا يجوز إنها تتولى الرئاسة أو القضاء\nفطبيعي إن الهدهد يستغرب من الموضوع\n¤طيب وهو كده ميبقاش في ظلم لقدرات المرأة، وخصوصا إن في نساء تولّت الرئاسة ونجحوا\nفكروا معايا كده،\nهل لمّا الضابط يقول للعسكري خليك واقف هنا، ده مكانك احرسه بحياتك عشان العدو ميدخلناش منه، ومحدش هيقدر يحمي المكان ده غيرك .... هل لما بيقول له كده بيكون ده في انتقاص من قدرات الجندي؟\nولّا كده الضابط بيوجه قدرات العسكري للمكان الصحيح والمناسب له عشان مصلحة الجندي نفسه و مصلحة الشعب في كده\nطيب ولو الجندي ده ساب مكانه وطمع في سلاح الطيران وهو غير مُؤهل لكده بسبب طول قامته مثلا بزيادة أو ضعف بنيانه أو أي سبب، مش هو كده بيعرض مصلحته ومصلحة الشعب للخطر والهلاك\nوده بالضبط معنى حديث رسول الله ﷺ:\n \" لَنْ يُفْلِحَ قَوْمٌ وَلَّوْا أَمْرَهُمْ امْرَأَةً\"\nالإسلام لم ينتقص من قدرات المرأة ولكنه وجهها في المكان المناسب لها،\nالمرأة مش مكانها إنها تختلط بالرجال...\nمش مكانها إنها تسافر من هنا لهنا عشان تعمل المعاهدات والاتفاقات...\nمش مكانها إنها تقود الجيوش للجهاد... مش مكانها تمسك القضاء وتحكم على ده بالقتل وعلى ده بقطع اليد، بجانب حمل وولادة وتربية!\nغير كده جسمها بيضعف مع تتابع الحمل والولادة، وتركيزها بيقل ومشاعرها بتغلب عليها ونتيجة لكل ده بتحتاج لشاهد تاني معاها في الخصومات وخلافه،\n\"وَاسْتَشْهِدُوا شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ 《وَامْرَأَتَانِ》 مِمَّن تَرْضَوْنَ مِنَ الشُّهَدَاءِ أَن تَضِلَّ إِحْدَاهُمَا فَتُذَكِّرَ إِحْدَاهُمَا الْأُخْرَىٰ ۚ\" \nفإزاي هتحكم بين الناس\nوخلال حكم رسول الله ﷺ وحكم الخلفاء الراشدين وخلال القرون الثلاثة الأولى خير القرون على الإطلاق مكانش في امرأة بتفكر بس كده مجرد تفكير إنها تطمع في حكم أو قيادة إدارة مدينة أو جيش مثلا؛ \nلأنها عارفة إن ده مش مكانها، وكون إن في نساء تولوا الرئاسة ونجحوا، فبغض النظر إن النساء دي معاها منظومة متكاملة بتساعدها على إدارة الحكم، \nفنجاحها ده بيكون على حساب ترك الأولاد وتربيتهم وتوفير مُرَبِّية وخادمة للبيت وواحدة تطبخ الأكل وتقعد بالولاد، \nفهمّ عشان يحققوا النجاح ده قلبوا سنة ربنا الكونية في فطرتهم واتمردوا عليها وشالوا مسؤوليات لا تخصهم وتخص غيرهم،\n فحتى نجاحهم ده مش نجاح حقيقي، ده نجاح مزيف ووهمي، وكمان يعتبر حالات نادرة جدا على مر التاريخ المعاصر كله، ومينفعش إطلاقا القياس على النادر ولا على حالات وهمية بالشكل ده\nثم الفلاح في حديث رسول الله ﷺ  معناه النجاح في الدنيا والآخرة، \nممكن الإنسان ينجح في الدنيا لكن مش معنى كده إن ربنا \nراضي عنه، وهيكون له النجاح في الآخرة برده\nفالهدهد شاف عند مملكة سبأ فساد في إدارة الحكم.. وشاف فساد تاني أخطر منه \nقال الهدهد وهو متضايق وقلبه متقطع:\nأنا لقيتهم بيسجدوا للشمس من دون الله\n\"وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ اللَّهِ وَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ فَصَدَّهُمْ عَنِ السَّبِيلِ فَهُمْ لا يَهْتَدُونَ\"\n☆طيب يا هدهد إنت إيه مشكلتك يعني يسجدوا للشمس ولّا القمر\nحد أنزل عليك كتاب وقال لك دافع عن الدين؟ \nهل ربنا أرسلك كرسول وقال لك ادعوا لله ؟ \nطب حد وصّاك وقال لك اعمل الخير وليك حسنات؟ \nلأ...طيب إيه مشكلتك يعني ،ما يعبدوا إللي يعبدوه وخلاص\n \nبس الهدد كان بيفكر:\nإزاي ناس ربنا خلقهم ويعبدوا غيره\nإزاي يبكوا ويتضرعوا لغير الله\n☆أيوة ماشي يا هدهد انت علاقتك إيه بالموضوع برده؟\nربنا عمل لك إيه مخليك تتضايق كده عشانه..دي حاجة لا تخصك أصلا\nقال الهدهد :\n\"ألاَّ يَسْجُدُوا لِلَّهِ الَّذِي يُخْرِجُ الْخَبْءَ فِي السَّمَاوَاتِ وَالأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ\"\nيعني  كأن لسان حال الهدهد بيقول:\nده ربنا يا بشر \nربنا إللي خلق السحاب وأنزل منه الأمطار المستخبية فيها وشق الأرض وأخرج منها النباتات المستخبية جوة الحبوب تحت الأرض بعيد عنا.. \nكل ده أخرجه لنا من المخابيء عشان ناكل ونشرب ونشبع ونعيش في أمانه ورزقه الواسع،\nبقى معقول ييجي بعد كده حد يعبد حد تاني غيره ؟! \nإزاي ما أدافعش عن حق الله في الألوهية\nأنا مأقدرش أشوف إلهي وَلِيّ نعمتي ومدبر أمري وأمر كل الخلائق يُكفَر بِيه ويُنتَقص من حقه وقدره وجلاله وأسكت\n☆الهدهد كان عنده حمِية للتوحيد وغَيرَة على جناب الله وحقه في العبودية لإنه خالق كل شيء،\nفِطرته ومروءته الحية دي خلّوه يرفض الوضع السيء ده ويبلغ سليمان عليه السلام لأنه نبي ومسؤول عن تعبيد الأرض لله عز وجل،\n\"الله لا إله إلا هو رب العرش العظيمَ\"\n¤عارفين زي إيه ولله المثل الأعلى\n؟\nلما يكون شخص معروف عنه إنه إنسان كويس بيعمل الخير وبيحسن للناس وبيحسن لك انت شخصيا وجمايله\nمغرقاك، زي مثلا الأم والأب،\nوييجي واحد يشتمه قصادك ويذم فيه وبينسب الخير ده كله لحد تاني مالوش أي لازمة أساسا في حياة أي حد حواليه، متخيل مشاعرك هتبقي عاملة إزاي لما تسمع ده في حقه؟  متخيل ردك هيبقى عامل إزاي وهتبقى نفسك تتصرف إزاي بسرعة وبكل الطرق  عشان تاخد له حقه من الشخص المؤذي الظالم الجاهل ده\nولله المثل الأعلى، ده كان إحساس الهدهد وأكثر من كده،\nعشان حبتين تلاتة قمح بياكلهم فقط في يومه، \nمعندهوش بيوت ولا قصور ولا مكيفات ولا مراوح ولا مُتع ولا أكل أشكال وألوان\nحبتين قمح هم إللي أثّروا فيه لدرجة إنه يسيب جنة سبأ ويروح لملك الأرض في الزمن ده عشان يتصرف ويحل الموضوع\nمملكة سبأ يا جماعة كانت آية في الجمال، فيها الأشجار والأنهار والثمار، فالهدهد كان في مكان خليه ينسى كل شيء، يعني  بالنسبة لطائر هيحتاج إيه أكثر من كده\n\"لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَةٌ ۖ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ\"\nفالهدهد برغم المُغريات دي كلها أول ما شاف ربنا بيُعصَى ويُكفَر بيه، نسي كل شيء ورجع لسليمان عليه السلام وقال له أنا ما لفتش نظري هناك إلا فساد عظيم بالمواصفات الفلانية، ولازم نتصرف عشان نغير ده\nفي عصرنا الناس تشوف التقدم إللي في أمريكا وألمانيا ودول الغرب بصفة عامة ويقعدوا يقولوا : \nدول ناس عندهم ...وعندهم... وعندهم.... شوفوا التقدم.. شوفوا النعيم.. شوفوا الحضارة... طيب ودينهم وعبوديتهم؟!! آخر حاجة الناس تفكر فيها\nشوفوا الهدهد إللي ماعندهوش صحيفة يتكتب فيها الحسنات والسيئات ربنا كافؤه بإيه بسبب موقفه ده:\n◇أولا :\nربنا مدحه في القرآن، بإنه طائر إيجابي وعنده همة وغيرة على التوحيد.\n◇ثانيا: \nربنا ضربه مثل لرسول الله ﷺ في الدعوة ولكل مَن يقرأ القرآن إلى قيام الساعة.. إزاي؟\nيعني شوفوا الهدهد عشان حبتين ربنا بيرزقه بيهم كل يوم، حس أد إيه إن ربنا عظيم ويستحق العبودية الخالصة، \nفراح دعا إلى عبودية الله وجاب أمة كاملة عشان يُسلِموا لله، \nفانتم ياللي عندكم كل شيء هتعملوا إيه؟!\n◇ثالثا:\nنهى رسول الله ﷺ عن قتل الهدهد،\nيعني هو كان هدهد واحد بس إللي عمل كده، لكن ربنا حَمى الفصيلة كلها بسبب إيجابيته وهمته العالية في الغَيرة على دين الله\n☆مش بيفكركم بقصة \"وكان أبوهما صالحا\" إللي قلناها في قصة الخِضر \nوعلى فكرة لما الهدهد عمل كده مكانش مستني الجزاء ده ولا كان طمعان في أي حاجة في المقابل، \nهو بس كان مُمْتن لله وغيور على جنابه بسبب حبتين القمح إللي بياكلهم في يومه \nسليمان عليه السلام لما سمع كلام الهدهد رد قال إيه؟\nقال:\nهنشوف انت صادق فعلا ولاّ بتكذب وبتقول القصة دي عشان تهرب من العقاب\n\"قالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ الْكَاذِبِينَ\"\n☆وهنا فيه فايدتين لنا نستفيدهم \n♡أول فائدة :\nإن لما حد يقول لك معلومة إنت متعرفهاش، مهما كنت شايف نفسك متعلم ودارس وعارف، والشخص إللي بيقولك المعلومة في وجهة نظرك مالوش أي وزن علمي،\nماتقولش أنا عمري ما سمعت الكلام ده والكلام ده غلط، وتبدأ تجادل من غير حتى ما تكلف نفسك تدوّر هل كلامه صح ولّا لأ\nويُذكر إن واحد من التابعين العلماء سمع عن مسألة شرعية معينة، فقال باستنكار: أنا أول مرة أسمع الكلام ده\nفصاحبه قال له: إنت جمعت العلم كله\nفالتابعي قال : لأ\nفصاحبه قال له: فهل جمعت نصفه؟ قال : لأ..\nفقال له: خلاص! اعتبر المعلومة دي في النصف اللي انت متعرفوش\n♡الفائدة الثانية:\nإننا لما تجيلنا معلومة عن أي حد نتثبت منها الأول ونتبين صحتها من عدمها.\nحتى لو كنت بتثق في الشخص إللي قال لك المعلومة دي زي ما بتثق في نفسك بالضبط،\nلإن احنا بشر، وممكن الكلام يتفهم غلط ويتنقل غلط، وممكن إللي بينقل الكلام ينقله من وجهة نظره هو وفهمه الشخصي، وانت لو كنت شفت أو سمعت الكلام مكانش هيوصلك بنفس المعنى إللي وصّلهولك بيه،\nفناخد بالنا قبل ما ناخد أي قرار نتأكد الأول من المعلومة زي ما سليمان عليه السلام عمل \nقال سليمان عليه السلام للهدهد خد رسالتي ووصلها لهم وهنشوف رد فعلهم إيه\nلأن الهدهد هو إللي جاب الخبر فطبيعي إن هو إللي يوصل رسالة سليمان عليه السلام لملكة سبأ،\nاذْهَب بِّكِتَابِي هَذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَانظُرْ مَاذَا يَرْجِعُونَ\" \nفأخد الهدهد رسالة سليمان وسافر من فلسطين لمملكة سبأ في اليمن وألقى رسالة سليمان لملكة سبأ وطار بعيد وقعد يراقب،\nالملكة فتحت وقرأت.. وأمرت باجتماع الوزراء والأعيان عشان تقول لهم عن رسالة سليمان عليه السلام،\nاجتمع الملأ، وقالت لهم:\nيا جماعة أنا وقع قدامي رسالة، ولما فتحتها لاقيتها من سليمان الملك المعروف، كاتب فيها: بسم الله الرحمن الرحيم ...أدعوكم للإسلام لله رب العالمين، فأسلموا لله وتعالوا منقادين مستسلمين له عز وجل تاركين عبادة الشمس وكل ما أنتم عليه من شرك ومعاصي.\n\"قالَتْ يَا أَيُّهَا الْمَلَأُ إِنِّي أُلْقِيَ إِلَيَّ كِتَابٌ كَرِيمٌ إِنَّهُ مِن سُلَيْمَانَ وَإِنَّهُ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ألاَّ تَعْلُوا عَلَيَّ وَأْتُونِي مُسْلِمِينَ\"\nفقالت لهم إيه رأيكم في الموضوع\nأنا مش هاخد أي قرار غير لما تقولوا رأيكم،\n\"قَالَتْ يَا أَيُّهَا الْمَلَأُ أَفْتُونِي فِي أَمْرِي مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ\"\nفقالوا لها:\nاحنا أقوياء وعندنا قوة تحمل وهنقدر نقاتل لو عايزة تعلني الحرب.. ولو عايزة السلام معاه وعدم الدخول في حرب فبراحتك برده...\nشوفي إللي انتِ عايزاه وإحنا تحت أمرك\n\"قَالُوا نَحْنُ أُوْلُوا قُوَّةٍ وَأُوْلُوا بَأْسٍ شَدِيدٍ وَالأَمْرُ إِلَيْكِ فَانظُرِي مَاذَا تَأْمُرِينَ\"\n فقالت لهم:\nبصراحة كده الملوك لما بيدخلوا بلد بيخربوها بالحرب وبيذلّوا حكامها وأشرافها وسادتها،\nفخلينا نبعتله هدية كده ونشوف هل هو من طُلّاب الدنيا وبيرضيه عطاياها فخلاص تبقى اتحلت ونعمل معاه معاهدة سلام دائم مقابل المال والعطايا، \nولّا هو مش هتلزمه هديتنا في شيء ومصمم عل طلبه إنه مش عايز مننا غير الإسلام زي ما بيقول فعلا\n\"قَالَتْ إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا وَجَعَلُوا أَعِزَّةَ أَهْلِهَا أَذِلَّةً ۖ وَكَذَٰلِكَ يَفْعَلُونَ ۩ وَإِنِّي مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ\"\nطار الهدهد وسبق الرّسل ورجع لسليمان وحكى له إللي شافه هناك وسمعه وهحيصل،\nفلما جاء الناس من طرف الملكة ومعاهم الرسول إللي هيوصل الهدية لسليمان عليه السلام ودخلوا عليه، اتصدموا من المنظر!! \nجنود من الجن والإنس والطير... مَلأ مالوش مثيل ومُلك مفيش في عظمته على وجه الأرض\nفقدموا الهدايا لسليمان عليه السلام وهمّ مفي قدامهم إلا إنهم ينفّذوا أوامر الملكة بكده، \nفغضب سليمان جدا لإنهم أساسا تخيلوا إنه من طُلّاب الدنيا، وإن أموالهم ممكن تُغريه وتفتنه عن نشر دين الله، وإنهم استهانوا بكلامه فقال لهم:\nأنا مش عايز أموالكم .. ربنا أعطاني أحسن وأعظم من إللي أعطاكم بكثير ..إنتوا إللي تفرحوا لما حد يعطيكم أموال وهدايا، لكن أنا لأ\n\"فَلَمَّا جَاءَ سُلَيْمَانَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِّمَّا آتَاكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ \" \nوقال للرسول بلهجة تهديد قوية:\nارجع لقومك تاني بالهدايا دي، احنا هنجيلهم بجنود مش هيقدروا عليها وهنخرجهم من سبأ أذلة متهانين لو همّ مجوش مُنقادين مستسلمين لدين رب العالمين \n\"ارْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُمْ بِجُنُودٍ لّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَا أَذِلَّةً وَهُمْ صَاغِرُونَ\"\nيا ترى بقى ملكة سبأ هتقاتل سليمان عليه السلام ، ولّا هتستسلم له؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 30, "l": "الجزء ٤٢ | إسلام ملكة سبأ | والحزء ٤٣ | معجزة موت سليمان | خبر النبي دانيال", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الثانية_والأربعون\n#قصة_سليمان_الجزء_الرابع\n#إسلام_ملكة_سبأ\nكنا واقفين المرة إللي فاتت عند سليمان عليه السلام لما قال لرُسل ملكة سبأ إنه هيأتيهم بجنود مش هيقدروا عليها وهيخرجوهم من أرضهم مذلولين،\nلما الرسل مشيوا بقى من عند سليمان عليه السلام ووصلوا لملكة سبأ -ويُقال إن اسمها بَلقِيس- حكوا لها إللي شافوه عند سليمان عليه السلام،\nفقالت أنا كنت متأكدة إنه مش هيكون زي ملوك الدنيا، واحنا مش هنقدر على قتاله فعلا ..\nفقررت إنها تروح مع وفد من كبراء قومها عشان تسمع من سليمان عليه السلام عن الدين إللي هو بيدعو إليه ده،\nسليمان عِرف إن الملكة هتيجي مع وفد لسليمان، سواء بقى عرف عن طريق الوحي أو عن طريق الهدهد أو هو نفسه استنتج كده، المهم إنه عرف وخلاص،\nفعرض مهمة على أفراد الملأ بتاعه قال لهم:\nمين فيكم يقدر يجيبلي العرش بتاعها قبل ما ييجوا عندنا هنا برغبتهم طائعين مستسلمين؟\n\"قَالَ يَا أَيُّهَا الْمَلَأُ أَيُّكُمْ يَأْتِينِي بِعَرْشِهَا قَبْلَ أَن يَأْتُونِي مُسْلِمِينَ\"\nغرض سليمان من طلبه ده إنه يورّيها جزء من قدرة ربنا وفضله عليه ونعمه العظيمة إللي وهبها له عز وجل \nفعفريت من الجن من جنود سليمان من جيش الجن قال بافتخار واقتدار وهمة عالية: \nأنا هجيبهولك قبل ما تقوم من مقامك، يعني قبل ما تقوم من مجلسك ده وتتركه، أو قبل ما مجلسك يكون انفض باللي فيه وكل واحد يروح لحاله،\nالمعنى بالظبط على خلاف بين المفسرين لكن المقصود يقول هجيبهولك بسرعة جدا،\nوأنا قوي هقدر أشيله، وأمين مش هضيع منه حاجة\n\"قَالَ عِفْريتٌ مِّنَ الْجِنِّ أَنَا آتِيكَ بِهِ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ\"\n☆ملحوظة:\nالعفريت هو المارد من الجن شديد القوة والدهاء والمكر والخُبث،\nوالعفريت من الجن ده أعلى في الخبث والدهاء والمكر من مَردة الجن، والمَردة أشد من الشياطين،\nفباختصار:\nالجن عموما كلهم كفار ما عدا فصيلة الجن المؤمن:\n \"وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَ فَمَنْ أَسْلَمَ فَأُولَئِكَ تَحَرَّوْا رَشَدًا ۩ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا \" \nلكن واحد تاني رد وقال :\nأنا أجيبهولك في غمضة عين \nربنا قال عنه:\n\"قَالَ الَّذِي عِندَهُ عِلْمٌ مِّنَ الْكِتَابِ أَنَا آتِيكَ بِهِ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ\"\n إللي عنده علم من الكتاب هو:\n إما جبريل عليه السلام، أو هو صاحب صالح لسليمان عليه السلام عنده اسم الله الأعظم الذي إذا دُعِيَ به أجاب.\n☆طب بما إنه مش جن وعنده قوة خارقة، هيجيب العرش في لمح البصر إزاي\nبالدعاء.. هيدعو الله باسمه الأعظم وهو موقن بالإجابة ويعلم إن الاسم ده إذا دُعِي الله به أجاب،\nعشان كده ربنا وصفه بإنه عنده علم؛ لإن علم أسماء الله وصفاته من أعظم علوم التوحيد\nفمجرد ما هيدعو هيلاقيه قصاده، وفعلا ده إللي حصل\nفي لمح البصر أو أسرع كمان بمجرد ما دعا باسم الله الأعظم سليمان عليه السلام لقى العرش قدامه!\nفلما سليمان شاف عرش بلقيس قصاده أول حاجة عملها \nكانت شكر النعمة\nوكأنه بيقول:\nمش هسمح للنعمة تلهيني عن ذكر الله وشكره،\nمش هسمح للنعمة تفتني عن ديني،\nأنا عارف إن النعم دي اختبار يا إما أشكر يا إما أجحد النعمة وأكفر، ولازم كل مرة أنجح في الاختبار ده،\nوإللي بيشكر بيشكر لنفسه لإن ربنا كده كده غني عن العاملين،\nوعبودية الشكر دي لمصلحتنا احنا لإن ربنا هيزيد الشاكر من فضله، واللي مش بيشكر النعمة مش هيضر ربنا بشيء..مش بيضر إلا نفسه\n\"فَلَمَّا رَآهُ مُسْتَقِرًّا عِندَهُ قَالَ هَذَا مِن فَضْلِ رَبِّي لِيَبْلُوَنِي أَأَشْكُرُ أَمْ أَكْفُرُ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ\"\nبعد كده وجّه سليمان أوامر للخدم بتوعه وقال لهم: \nغيّروا في شكل العرش بتاعها شوية بحيث لما تيجي نخليها تشوفه ونشوف رد فعلها \n\"قَالَ نَكِّرُوا لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِي أَمْ تَكُونُ مِنَ الَّذِينَ لَا يَهْتَدُونَ\"\nوالتغيير إللي حصل هنا يا جماعة كان تغيير في الشكل يعني يضيف جواهر مثلا بطريقة معينة، لكن مش تغيير في أصل العرش؛ لأنه مش بتاعه عشان يتصرف فيه\n☆طيب ليه سليمان أمر جنوده اصلا إنهم يغيروا التغيير ده\nإحنا عارفين إن سليمان عليه السلام ذكي وسريع البديهة،\nمن يوم ما كان بيحكم مع سيدنا داود في الخصومات،\nفهو حب يعرف هل عندها وعي وبصيرة وهتقدر تتعرف علي عرشها رغم التغييرات إللي عملوها فيه دي،\nولّا هتكون من النوع إللي بيدخل عليه الخدع والتزييف وبيتلخبط ومش بيعرف يميز الحق من الباطل\nفلما جاءت ملكة سبأ لسليمان استقبلها وورّاها العرش وسألها: \nده العرش بتاعك\nفقالت:  كأنه هو\nهي مقدرتش تقول 《لأ》 لأنه يشبه العرش بتاعها جدا، وفي نفس الوقت مش قادرة تقول《أيوة》 لأن العرش بتاعها في سبأ، والمسافة بين فلسطين وبين سبأ كبيرة...فإزاي العرش بتاعها يبقى موجود هنا\n\" فَلَمَّا جَاءَتْ قِيلَ أَهَكَذَا عَرْشُكِ قَالَتْ كَأَنَّهُ هُوَ \"\n☆فهي كانت امرأة صادقة في بحثها عن الحق؛ لأنها لو قالت لأ مش عرشي وعرشي أحسن \n \nكان هيظهر إنها مخادعة وعايزة تخدع سليمان عليه السلام  وتتظاهر إنها تابعة له عشان تحافظ على ملكها،\nولو كانت قالت لأ ده مش عرشي، يبقى هي أنكرت بدون بيّنة، وكل ده هيبين شخصيتها قصاد سليمان عشان يعرف يتعامل معاها إزاي\nفكلامها كان دقيق قالت : كأنه هو \nفالعلماء قالوا لعل ربنا وفّقها للهداية بسبب صدقها ده\nسليمان عليه السلام كان أمر الجن إنهم يبنوا قصر عظيم من الزجاج ، وأمَر إن تحت القصر الزجاجي يكون في مية بتجري  بغزارة،\nوكان سليمان عليه السلام قاعد في القصر ده ومعاه خدمه من الجن والإنس والطير مستني الملكة تدخل عليهم، وبالفعل الخدم وصلوها عند القصر..\n\"قِيلَ لَهَا ادْخُلِي الصَّرْحَ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا\"\nيعني لما وصلت ، بصت كده، وتخيلت إنها لازم هتمشي في المية عشان تدخل، فرفعت ملابسها الساترة الطويلة الملامسة للأرض وكشفت عن الساقين بتوعها عشان تعدي لجوة من غير ما تبل هدومها، \n☆واخدين بالكم\nامرأة كافرة وهدومها كانت واصلة للأرض\nالمهم،\nسليمان نبهها إن دي مش مية، ده قصر معمول من الزجاج النقي جدا، والمية تحت منه\n\"قَالَ إِنَّهُ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ\"\nوكان غرض سليمان عليه السلام من بناء القصر ده إنه يخليها تشوف مُلك هو أعظم من ملكها وبالتالي مفيش حاجة ممكن تُصرفه عن نشر دين الله، \nوكمان عشان ميكونش عندها شك في قدرة ربنا بعد كده وعطاؤه وفضله لعباده الموحدين،\nمش بقى عشان إنه يشوف رجلها فيها شعر ولّا لأ زي ما الإسرائيليات افترت عليه والعياذ بالله من سوء أدبهم وفحش لسانهم مع أنبياء الله \nبعد ما بلقيس شافت كل ده قالت:\n\"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ\"\nأسلمت بلقيس مع سليمان لله وحَسُن إسلامها،\nمفيش بقى أي دليل على إن سليمان عليه السلام تزوجها أو لأ، ومفيش دليل برده إن أم بلقيس كانت من الجن،\nوإن الجن مكنوش عايزين سليمان يتزوجها\nكل الكلام ده مفيش عليه أي دليل صحيح ولا يضرنا الجهل به\n☆سؤال بقى،\nليه سليمان عليه السلام هدد ملكة سبأ بالحرب ؟ وليه يفرض عليها الدين بالقوة؟ \nوليه ما قبلش الهدية و بادل الإحسان ده بإنه يدعوها بالحسنى واللين بدل القوة والتهديد\n¤سليمان عليه السلام مَلِك ومش أي مَلك ، ده ربنا جمع له مُلك الأرض كلها بالجن والطير كمان،\nوالمَلِك لابد أن تكون له الطاعة والانقياد، وخصوصا لو كان بيؤمر بالخير وتوحيد الله، فمينفعش حد يخالفه في كده\n وإللي يخالف يجب قتاله، لإنه بُيفسد المملكة الواسعة دي وبينشر الكفر ويفتن باقي الموحدين في مُلكه\nعشان كده كان كل فترة يطلع مع جيشه للجهاد في سبيل الله عشان ينشر التوحيد\nفبلقيس ملكة سبأ استقلت عن مُلك سليمان بعبادتها للشمس فكان واجب على سليمان عليه السلام إنه يرجعها تحت حكمه مرة ثانية\nوهو لم يُرغِم بلقيس على الدخول في الإسلام نفسه بالعافية، فالجهاد أصلا ربنا لم يشرعه عشان يُرغم الناس إنهم يدخلوا في الإسلام، \nولكن عشان تكون كلمة الله هي العليا في الأرض، وتكون السيطرة لشريعة الإسلام على العباد والمعاش والقوانين؛\nلإن الإسلام دين عادل، وأي حكم تاني غيره فيه ظلم للناس، وإللي عاوز يستمر على عقيدته براحته، لكن في ظل حُكم الإسلام\nفعرض عليهم في الأول الإسلام وإنهم ينقادوا تحت حُكمه هو تحت شريعة رب العالمين ويتركوا عبادة الشمس،\nفلما حاولوا يغرُوه بالمال جت رسالته التانية عليه السلام  شديدة اللهجة بإعلان القتال عشان يضم حكم بلادهم تحت حكم الشريعة؛ لإن عادة الملوك إنهم بيفضّلوا الدنيا ومش بيتنازلوا عن مُلكُهم أبدا وبيقاتلوا عليه لحد آخر نَفَس ومش ييبقوا عايزين حد يقول لهم ده حلال وده حرام ولا يتحكم فيهم، \nإلا لو حد اضطرهم لكده بالقوة، والأقوى هو إللي يكسب.. ودايما من حق الأقوى فعلا إن هو اللي يفوز طالما أثبت إنه أقوى\nفلو أخدنا بالنا هنلاقي إن الملأ قالوا لبلقيس: إحنا أصحاب قوة فعادي إننا نحارب سليمان لو  خيار الحرب هو اللي انتي شايفاه.. \nفهمّ كانوا مستعدين للحرب كعادة الملوك.. \nلكن بلقيس كانت عاقلة وعايزة تحافظ على ملكها فاختارت الحيلة،\nوطبعا لو كان سليمان عليه السلام دعاها للإسلام من غير ما يخوّفها بالحرب مكنتش استجابت ولا بدأت تبحث عن حلول أصلا\nفي ناس كده، ماينفعش معاها غير منطق القوة\nومش بس في الحرب، ده حتى في المعاملات اليومية، في نوعيات كده لازم تكلمهم بمنطق القوة عشان يسمعولك، وياخدوا كلامك على محمل الجد\nده غير كده إن الأمور بتتقاس بالنتائج هل كانت إيجابية ولّا سلبية، يعني نتيجة تصرف سليمان عليه السلام ده كانت إيه؟ مش كانت إنهم أسلموا بإرادتهم في الآخر بعد ما جاءوا بالخوف من القوة وشافوا وسمعوا بنفسهم عن التوحيد وآمنوا بدون تهديد أو سلاح؟\nوهو ده المطلوب، فهو كان أدرى الناس بأفضل طريقة للتعامل..\nأقرب لكم المعنى\nمثلا لما نشوف طبيب بيفتح بطن مريض ويقطع من لحمه ويخيط ويكوي والدم سايل والمنظر مرعب\nلو شوفنا ظاهر الموضوع هنقول:\nإيه الطبيب إللي معندهوش قلب ده \n \nلكن لما تكون النتيجة إن المريض ده عاش بسبب أفعال الطبيب هنشكر الطبيب\nحتى في الدعوة إلى الله والدفاع عن دينه بالحجج والبراهين، ممكن تشوف واحد بيناظر واحد تاني بأسلوب -من وجهة نظرك انت- أسلوب شديد أو عنيف أو هجومي..\nونسيت إنه بيوجه له هو أسلوب الكلام ده مش ليك إنت،\nفتفكر إن إللي بيدعي ده بينفر الناس و...و... فتدخل في الحوار وتبدأ تهاجم لأنك أخدت الكلام على نفسك والكلام غير موجه ليك أصلا،\n يعني ممكن جدا يكون بيعامله بالأسلوب المناسب له دلوقتي في اللحظة دي لأنه بيعمل بقول قول رسول الله ﷺ  : خاطبوا الناس بما يعقِلون\n..\nفأكيد لكل نوع معين من البشر أسلوب خاص للتعامل معاهم بشكل يحقق المصلحة بأفضل نتايج\nفسليمان عليه السلام لو كان بيتكلم مع عامة شعب سبأ خطابه كان هيكون مختلف عن خطابه مع بلقيس والملأ بتاعها، لأن دعوة الملوك غير دعوة عوام الناس\n☆عندنا بقى ملحوظة مهمة نختم بيها قصة سليمان مع ملكة سبأ\nاحنا طبعا شوفنا حكمة بلقيس ملكة سبأ، وشوفنا إزاي الوزراء كانوا متسرعين وهي كانت أحكم منهم،\nوربنا أقر حكمتها لما قالت:\n\"إن الملوك إذا دخلوا قرية أفسدوها وجعلوا أعزة أهلها أذلة\" فقال: \"وكذلك يفعلون\"\nيعني ربنا بيقول إن كلام ملكة سبأ فعلا صحيح وده حال ملوك الدنيا،، فكون القرآن يُقر معلومة على لسان ملكة فده تشريف للملكة دي إنها مش واحدة عادية\nوده بيدل على حكمتها وعلى فقه الواقع عندها ومعرفتها بعواقب الأمور،\nوإلا اشمعنى يعني هي عارفة الملوك بيعملوا إيه والوزراء اللي معاها مايعرفوش\nفواضح إن هي نفسها كامرأة لها عقلية مختلفة عن باقي النساء مكّنتها من سياسة الشعب وحكمه في الفترة دي بحكمة و رُشد،\nوحتى العلماء كمان أثنوا على إنها اتصرفت بحكمة ووازنت بين المصالح والمفاسد وطلعت بحل يخليها تتبين هل سليمان فعلا من ملوك الأرض إللي بيفسدوا؟ ولّا هو نبي وعايز الدين ومصلحة العباد؟\nلكن يا جماعة برغم كل ده ومهما كانت بلقيس حكيمة وأفضل من رجال كتير فهي حالة شاذة وماينفعش نقيس على الشاذ\n \nلإن القواعد مش بتتبني على الاستثناءات...\nفمش معنى إن الملأ الرجال هنا كانوا متسرعين وأخدتهم الحمية والتسرع للحرب والصدام، إن ده عادة الرجال كلهم على طول الخط، لأ، لكل قاعدة شواذها،\nولو راجعنا التاريخ هنلاقي أمثلة كتييير جدا على حكمة الحكام والوزراء الرجال،\nبعكس أمثلة قليلة جدا للنساء، \nفهي حكمتها ورُشدها في القصة كلها واضحين وواضح إنها مختلفة عن باقي إللي حواليها،\nلكن اختلافها المميز ده ما يخليناش نعتبرها قاعدة بقى والناس تقيس عليها ويقعدوا يطالبوا بتولية النساء لأمور الحكم والخلافة\nكل واحد له دوره زي ما قلنا في مثال الجندي والضابط المرة إللي فاتت\nياترى بقى إيه إللي حصل مع سليمان بعد كده،\nده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء\n#الحلقة_الثالثة_والأربعون\n#معجزة_موت_سليمان\n#خبر_النبي_دانيال\n اتكلمنا المرة إللي فاتت عن قصة سليمان مع ملكة سبأ، وشوفنا إن سليمان عليه السلام كان بينشر دين ربنا في الأرض،\nواستمر الحال ده مع سليمان عليه السلام فترة من الزمن، وكان عنده جيش من الجن زي ما قلنا قبل كده،\nفاكرين لما قلنا إن ثاني مسجد بُني في الأرض كان المسجد الأقصى وإللي بناه كان يعقوب عليه السلام\nخلال السنين دي كان المسجد اتخرّب، فداود عليه السلام كان بدأ يجدده، لكنه مات قبل ما يكمّل تجديده،\nفأوصى سليمان عليه السلام إنه يكمل من بعده تجديده وترميمه،\nفأمر سليمان عليه السلام الجن بإنهم يتولوا مهمة البناء والترميم دي،\nوكان عليه السلام بيُشرف عليهم بنفسه، فربنا كان مسخّر الجن لخدمة سليمان عليه السلام ، سواء المؤمن منهم أو الكافر، \n\"وَمِنَ الْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ ۖ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ السَّعِيرِ\"\nكان مجموعة منهم بيبنوا له القصور والتماثيل وأحواض كبيرة يُجمع فيها الماء،\nومجموعة تانية كانوا بيغوصوا في البحار يستخرجوا له منها الجواهر واللآلئ،\n\"يَعْمَلُونَ لَهُ مَا يَشَاءُ مِن مَّحَارِيبَ وَتَمَاثِيلَ وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَّاسِيَاتٍ\"\nوبيعملوا كمان أعمال مختلفة، و مكنش حد يقدر يخرج عن أمر سليمان عليه السلام،\n\"وَمِنَ الشَّيَاطِينِ مَن يَغُوصُونَ لَهُ وَيَعْمَلُونَ عَمَلًا دُونَ ذَٰلِكَ وَكُنَّا لَهُمْ حَافِظِينَ\"\nو أي واحد من الجن يعصي أمر سليمان عليه السلام، كان بيتم ربطه بالأغلال والسلاسل أو ربنا بيعذبه بالنار.\nالشياطين كانوا بيقولوا للناس في زمن سليمان عليه السلام إنهم كانوا بيعلموا الغيب،\nوكانت الناس مصدقاهم لأنهم كانوا بيشوفوا قوة الجن وقدرتهم الخارقة، \nوكان سليمان بيقول لهم إن ده مش صح، فلا يعلم الغيب إلا الله، لكن الناس مكنوش مقتنعين،\nفسليمان عليه السلام دعا ربنا إنه يُخفِي عن الجن موته عشان يثبت للناس إن الجن كدابين في زعمهم العلم بالغيب..\nكان سليمان عليه السلام كل فترة بيختلي بنفسه عشان يتعبّد لله ومبيسمحش لحد إنه يقطع عليه خلوته الإيمانية دي،\nوكان بياخد معاه إللي بيحتاجه من الأكل والشرب،\nزي ما رسول الله ﷺ كان بيخرج يتعبد في غار حراء قبل البعثة\nفسليمان عليه السلام عرف إنه هيموت قريب؛ لأن الأنبياء زي ماقلنا قبل كده بيتم تخييرهم قبل ما يموتوا بين الموت وبين المُكْث في الدنيا \nففي يوم كان سليمان عليه السلام بيتابع شغل الجن في ترميم المسجد الأقصى وبيشرف عليهم بنفسه عشان مايكسلوش عن الشغل\n☆إيه ده، يعني المسجد الأقصى هو هيكل سليمان إللي اليهود بيقولوا عليه\nلأ طبعا،\nموضوع هيكل سليمان ده أصلا حاجة من اختراع اليهود مش موجودة \nيعني المسجد حاجة والهيكل ده حاجة تانية،\nوالدليل على كده إن رسول الله ﷺ  قال عن سليمان عليه السلام إنه بنى بيت المقدس، إللي هو المسجد الأقصى زي ما قلنا من شوية\nومعنى البناء هنا يعني هو إللي أعاد بناء المسجد الأقصى، يعني هو كان موجود ولكنه أعاد بناؤه،\nده غير إن في كتب اليهود في اختلاف بين علماء اليهود على مكان الهيكل وعلى شكل الهيكل نفسه عامل إزاي\nيعني متخيلين ناس بتدور على حاجة مش عارفين هي إيه أصلا\n◇طب ثواني كده، يعني إيه أصلا هيكل سليمان\nالهيكل يعني المعبد، وفي اللغة العِبرية الهيكل معناه بيت الإله، واليهود بيقولوا إن الهيكل ده هو أهم مكان للعبادة، وإن سليمان بناه لهم ولديانتهم،\nوبيقولوا إنه موجود تحت المسجد الأقصى، عشان كده بيحفروا تحته دلوقتي عشان عايزين يوقعوه\nالمهم،\nسليمان عليه السلام كان واقف وساند دقنه على العصاية بتاعته بيراقب سير العمل وهمّ شايفينه باصص عليهم طول الوقت،\nو هو في الوضع ده ربنا قبض روحه \n \nالجن شايفينه مفتح \n وباصص عليهم...لكن هو في الحقيقة ميت\nواستمر الوضع كده فترة زمنية.. أد إيه بالضبط؟ محدش يعرف، في علماء قالوا أسبوع .. علماء تانيين قالوا شهر.. علماء غيرهم قالوا سنة\nالعلم عند الله والموضوع مش هيفيدنا كثير، أهم حاجة نعرف إنه قعد فترة ميّت على الأقل أسبوع،\nوالجن مكنتش تعرف وعمالين يشتغلوا بدون راحة، ومحدش كان يقدر يقرب من سليمان عليه السلام،\nوطبعا همّ لم يشكّوا إن سليمان عليه السلام كان ميت، مع إنه مكنش بياكل ولا بيشرب؛ لأنهم عارفين الأنبياء وضعهم مختلف،\nيعني ممكن ربنا بيعطيهم القدرة في أوقات معينة إنهم يستغنوا عن الأكل والشرب،\nزي موسى عليه السلام لما صام ثلاثين يوم وأفطر وبعدها صام عشر أيام تانية بأمر من ربنا ومكنش بياكل ولا يشرب،\nوخدوا بالكم إن أجساد الأنبياء لا تتحلل ولا تأكلها دواب الارض، يعني أجساد كوووول الأنبياء والرسل زي ماهي في القبور لم تتعفن ولم تتحلل\nفربنا أرسل دودة الأرض تأكل عصا سليمان عليه السلام إللي هو كان ساند عليها،  \nفربنا أرسل دودة الأرض واسمها 《الأَرَضَة》 وقعدت تأكل عصا سليمان عليه السلام إللي هو كان ساند عليها بدقنه،\nفقعدت تاكل فيها من تحت لحد ما العصا ضعفت وبقت هشة فوقعت، وسقط سليمان عليه السلام على الأرض..\n\"فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِ إِلَّا دَابَّةُ الْأَرْضِ تَأْكُلُ مِنسَأَتَهُ\"\nوهنا عرفت الجن إن سليمان عليه السلام كان ميت بقاله فترة وهمّ ميعرفوش حتى هي أد إيه ولا من إمتى،\nواعترفوا بحسرة إنهم فعلا لو كانوا يعرفوا الغيب مكنوش استمروا في التعب والذل والمشقة المستمرين كل ده \n\"فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ أَن لَّوْ كَانُوا يَعْلَمُونَ الْغَيْبَ مَا لَبِثُوا فِي الْعَذَابِ الْمُهِينِ\"\nوطبعا الناس عرفت إن الجن كانوا بيكذبوا عليهم وإنهم مايعرفوش الغيب ولا حاجة\nمدة حكم سليمان عليه السلام كانت أربعين سنة، ومدة حكم داود عليه السلام كانت أربعين سنة..فيكون مجموع المُلك النبوي المستقر الوحيد لبني إسرائيل هو ثمانون عام فقط\n☆صحيح ...هو فين بني إسرائيل مسمعنالهمش صوت خلال السنين دي كلها\nفي عهد داود عليه السلام كان بنو إسرائيل بيحبوه وكان ملك عادل،\nسليمان عليه السلام كان عادل وكمان كان ملك قوي ربنا سخّر له كل حاجة فمين مستغني عن عمره عشان يقف في وجه ملك زي سليمان عليه السلام\n◇إيه بقى إللي حصل بعد موت سليمان عليه السلام \nابن عباس رضي الله عنه بيقول إن بعد موت سليمان عليه السلام، الجن بدأت تبحث تحت عرش سليمان عن الكتب التي كان بيكتبها كاتب سليمان، \nويُقال إن الكاتب ده كان اسمه \"آصف\"، وكان بيكتب فيها كل شيء عن سليمان عليه السلام، عن الملك وعن الشريعة والوقائع والأحداث.. كل شيء.. زي دواوين الحكم كده مثلا..\nفلما الشياطين أخرجت الكتب دي، بدأوا يكتبوا ما بين السطور كلمات السحر والكفر ودعاء غير الله،\nوخرجوا على الناس إللي همّ بني إسرائيل، وقالوا لهم إن دي كتب سليمان،\nوإنه كان مسخّر الجن والطير والريح بالسحر ده،\nوالناس قرأت الكتب لقت فيها فعلا كلمات السحر والكفر بالله ودعاء غير الله ، فصدقوا للأسف،\n\"وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ ۖ\"\nوانتشر بين الناس إن سليمان عليه السلام كان بيتعامل بالسحر وكان كافر بالله\nفربنا دافع عن سليمان عليه السلام وقال إنه لم يكفر ولم يكن ساحر وإن الشياطين هم إللي كفروا بيعلموا الناس السحر، وبيعلموهم السحر إللي أُنزل على المَلَكِين هاروت وماروت\n\"وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ\"\n☆مين هاروت وماروت دول\nالمَلَكِين دول ربنا أنزلهم وجعلهم في صورة رجلين صالحين في مدينة بابل في العراق،\nمهمتهم إنهم يدافعوا عن سليمان عليه السلام من الكلام إللي بيتقال عنه إنه ساحر، \nفكان الملكين بيعلموا الناس السحر ويوضحوا لهم إن في فرق بين السحر وبين النبوة،\nوإن السحر ده ممكن أي حد يتعلمه، أما النبوة فهي اختيار من الله عز وجل ومش حاجة مُكتسبة، \nيعني مفيش واحد يعبد ربنا لزمن معين أو يتعلم علم معين فربنا يرزقه النبوة ويبقى نبي، لأ...النبوة والرسالة اصطفاء خااالص من عند ربنا\nلكن السحر ممكن تتعلموه من أي حد وألاعيبه بتبقى كده و بنوريها لكم من باب إنكم تتعلموا الشر مخافة أن تقعوا فيه، وعشان تعرفوا الفرق بين النبوة وبين السحر، \nعشان لما يجيلكم نبي من أنبياء الله لا يتهمه أحد بإنه ساحر وتعرفوا تميزوا هل هو نبي والا ساحر،\nلكن لازم تكونوا فاهمين إن السحر ده كُفر بالله، و احنا فتنة واختبار وابتلاء من الله ليكم باللي بنعلمهولكم ده،\nفخدوا بالكم هتضيعوا نفسكم لو مسمعتوش تحذيرنا ليكم واستخدمتم السحر إللي احنا علمناهولكم ده\n\"وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ\"\nطيب بني إسرائيل عملوا إيه\nللأسف مسمعوش الكلام وبقوا بيتلقوا العلم ده ويطبقوه، وبقوا يتعلموا من السحر الأمور إللي يفرقوا بيها بين الزوج وزوجته ويخلوهم في كرب وشقاق، \n\"فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ\"\nلكن ربنا علمنا أمر مهم جدا، وهو إن مفيش ضرر بيتم عن طريق السحر  ومس الجن إلا بإذن الله،\nيعني مش هيحصل أي أذى غير لما ربنا يأذن بكده.. وعلمنا إننا نلتزم بالأذكار وبكثرة قراءة الرقية الشرعية وقراءة  القرآن بالذات سورة البقرة،\n\"وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ\"\nاستمر الإعتقاد بإن سليمان عليه السلام ساحر حتى عهد رسول الله ﷺ، فلما تكلم رسول الله ﷺ عن قصة سليمان وإنه من أنبياء الله، اليهود قالوا: \nده كان ساحر وكافر بالله\nفنزل القرآن يُبرئ سليمان عليه السلام ويحكي عن إللي شرحناه من شوية ونزلت الآية:\n\"وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ ۖ وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ \"\nبعد ما الشياطين فتنت الناس بالافتراء الكاذب على سليمان عليه السلام انتشر الفساد والكفر في بني إسرائيل تااااااني\nوانقسم الناس على أنفسهم، وبدأ الظلم بينهم والتعدي على بعض والبُعد عن كل الفضائل\nاحنا عارفين إن بني إسرائيل كانوا ١٢ سِبْط .. 12 قبيلة يعني لو تفتكروا..\nفانقسم الـ١٢ سِبْط لقسمين: \nعشر أسباط في قسم اتفقوا على قيادة معينة، وسكنوا شمال فلسطين وكَوّنوا مملكة إسرائيل،\nوالقسم التاني: الاتنين الأسباط إللي فاضلين،\nدول اتفقوا على قيادة تانية خالص، وسكنوا جنوب فلسطين وكَوِّنوا مملكة يَهُوذَا..\nوكان السِبْطين دول هما:\n◇سِبْط يَهُوذا إللي كان فيه المُلك قبل كده زي داود وسليمان عليهما السلام،\n◇والسبط التاني سِبْط بنيامين.\nمملكة بقى الشمال استمرت حوالي 200 سنة، كلها كُفر وظلم وفساد\nلحد ما ربنا سلّط عليهم الآشوريين إللي جاءوا من العراق، وأفنوا مملكة إسرائيل، وأخدوا معظم شعب إسرائيل وبعتروه وشتتوه في العالم .. باعوهم هنا وهناك وشردوهم لحد ما فنوا عن آخرهم،\nوبكده انتهى تمااااااما من الدنيا بكاملها كل نسل العشرة أسباط دول\nيعني مابقاش في التاريخ حاجة اسمها يهودي من نسل الأسباط العشرة..\nيبقى اتبقى عندنا فقط \"ممكلة يهوذا\" إللى موجودة في الجنوب، وإللي فيها بيت المقدس.\nومن هنا جت تسمية اليهود، نسبةً إلى نسل يهوذا إللي فيه المُلك.. \nواسم اليهود مكنش معروف أيام موسى عليه السلام ولا حتى في باقي الأنبياء من بعده،\nوالفَرعين بتوعهم دول من الأسباط  -إللي همّ يهوذا وبنيامين- همّ إللي هيكملوا معانا الأحداث لحد ما ربنا يرسل عيسى عليه السلام\nاستمرت ممكلة يهوذا بعد سقوط مملكة إسرائيل حوالي مائة وخمسين سنة، خلال الـ١٥٠ سنة دي حصلت أحداث في مملكة يهوذا،\nالأحداث دي من الإسرائيليات،\n لكنها من قسم الإسرائيليات اللي لا تُصَدَّق ولا تُكَذَّب زي ما شرحنا قبل كده، يعني ممكن أن تُروَى عادي،\nوهي موجودة في البداية والنهاية لابن كثير، فأنا هقولها من باب فقط إننا نربط الأحداث ببعض عشان نبقى متخيلين الأحداث ماشية إزاي\n《《انتشر الفساد في بني إسرائيل، فربنا بعث فيهم نبي من تاني اسمه شَعِيَا أو أشْعِيا، الاتنين صح.. وكان مَلِك بني إسرائيل في الزمن ده اسمه \"حِزْقِيا\" وكان مطيع للنبي أشعِيا، لكن بنو إسرائيل كانوا فاسدين كعادتهم.. \nفي يوم مرض الملك وكان في رِجله قُرحة،\nفي نفس الوقت ده كان ملك بابل مُتجه لبيت المقدس ومعاه ستمائة ألف جندي عشان يغزو بيت المقدس والملك ده كان اسمه \"سَنْحَاريب\"،\nوالناس خافت، ووصل الخبر لملك بني إسرائيل الطيب، فسأل الملك النبي أشعِيا: ربنا أوحى لك بإيه عن الجنود دي\n  فالنبي قال: لم يوحي إليّ بشيء عنهم.. ثم نزل وحي على النبي بعدها إنه يقول للملك إنه يكتب وصيته عشان خلاص هيموت قريب..\nفقعد الملك يدعي ربنا إنه يُمدّ له في أجله، وكان ملك صالح زي ما قلنا، فربنا استجاب دعاؤه، وأمد له في عمره خمسة عشرة سنة\n☆بس مش الآجال مكتوبة ؟ ومش احنا ماينفعش ندعي بطول العمر\nأيوة مكتوبة في اللوح المحفوظ، وفعلا زي ما ربنا قال:\n\"وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لا يَسْتَأْخِرُونَ سَاعَةً وَلا يَسْتَقْدِمُونَ\"\nلكن ده عن الأجل النهائي، فمكتوب عند ربنا إن أجله النهائي هيكون بعد 15 سنة، \nوطولة العمر الزيادة دي مكتوب إنها هتحصل، وإن عمره كده كده كان هيبقى تام بال15 دول،\nلكن من أسباب تمام العدد بشكل كامل هيكون في دعوة من العبد الصالح ده ربنا هيستجيب لها،\nفكل ده مكتوب في اللوح المحفوظ وإللي هو  في علم الله وحده واحنا بنعرفه فقط بعد ما بيقع مش قبلها..\nفبالتالي الملك الطيب ده ماتأخرش عن أجله لحظة\nوبالنسبة للدعاء بطولة العمر:\nفاحنا يجوز عادي في ديننا الدعاء بطول العمر لنفسنا أو لغيرنا،\nلكن نقيد الدعاء ده بأمور صالحة تقرّبنا من ربنا؛ لإن فيه ناس كل ما زاد عمرها زادت بُعدا عن الله، والنبي ﷺ لما كان بيدعي لحد من الصحابة بطولة العمر كان بطبيعة الحال معروف إن عمرهم كله في طاعة..\nفاحنا نقول مثلا في الدعاء :\nربنا يطوّل عمرك في طاعة الله، أو في الخير ، أو فيما يرضي الله وهكذا.\nفالملك الصالح شكر ربنا على استجابة دعاؤه وضاعف من تضرعه وذله لله،\nفربنا شفى له قدمه من القُرحة وأهلك جيش مَلك بابل ، ماعدا سنحاريب الملك، ومعاه خمسة من أصحابه، \nوكان في أصحابه دول واحد اسمه 《بُخْتُنَصَّر》 \nفأخد مَلك بني إسرائيل الطيب الناس الستة المهزومين دول، وربطهم في القيود،  وجعل الجنود بتوعه يطوفوا بيهم وسط الناس في البلد إذلالًا لهم.. \nوبعدين ربنا أوحى للنبي أشعِيا إنه يقول للملك إنه يرسل الست أشخاص دول لبلادهم عشان يحكوا إللي حصل لهم وينذروا قومهم ويخوفوهم منه..\nفلما رجع سنحاريب لبابل وحكى إللي حصل معاهم، السحرة والكهنة قالوا له:\nماحنا قلنا لك عن رب الناس دي وإن محدش بيقدر عليه من زمان\nوعاش سنحاريب بعدها سبع سنين ومات..\nلما خلصت الـ15 سنة جاء أجل ملك بني إسرائيل النهائي فمات،\nبعد موته بني إسرائيل فجَرُوا وفسقوا  لأبعد الحدود، وانتشر شرَّهم في كل اتجاه.. فأوحى الله لنبيه أشعِيا، إنه يوعظهم وينذرهم ويذكرهم بالله، وإنه هيعاقبهم لو خالفوا أمره واستمروا في طغيانهم.. \nفلما خلص كلامه معاهم ومواعظه، راحوا قايمين عليه واعتدوا عليه.. كانوا عايزين يقتلوه..\nفهرب منهم وطلع يجري لحد ما عدى على شجرة ، فاتفلقت قدامه عشان يدخل فيها فدخل واختبأ منهم،\nفالشيطان مسك طرف ثوبه وخلاه بره الشجرة ، فشافوه، فنشروا الشجرة والنبي أشعِيا جواها، وقتلوه قاتلهم الله\nومع ذلك ربنا أرسل لهم نبي تاني اسمه أَرْمِيا، \nوكان برده بيوعظهم وينهاهم عن فسقهم و شرهم وإنهم لو مستجبوش ربنا هيرسل عليهم ملك جبار قاسي يخرب بلدهم ويقتلهم، وفعلا أرميا نفّذ كلام ربنا كله وحذرهم ، لكنهم كذبوه وقالوا عليه مجنون\n》》\n¤طب هو ليه ربنا يحذر بني إسرائيل أصلا \nعشان يعلمهم ويعلم كل الأمم إللي هتيجي بعد كده، إن مهما كانت جرائم الإنسان وذنوبه عظيمة وكتيرة، فلو تاب وأصلح ومشي في الطريق الصح، ربنا هيتوب عليه ويقبله ويعفو عنه،\nلكن لو أصر على طغيانه وعصيانه، ربنا هيعاقبه ويعذبه بألوان العذاب،\nيسلط عليه حد يُؤذيه مثلا، أو يبتليه بمرض يُذله ويقعده، أو يبتليه بفقر يفضح ستره ويحوِجه للسؤال مثلا... \nولو حد فلت من عقاب الدنيا لحكمة إلهية، فعقاب الآخرة موجود\nفي الوقت ده كان مَلك بابل في بلاد العراق معروف بقوته وبطشه،\nفكان يقود جيوشه عشان يحتل البلاد، الملك ده كان اسمه 《بُخْتُنصّر》\n☆فاكرين لما قلنا إن الأرض حكمها أربعة ملوك: اثنين كفار واثنين مؤمنين؟\nالاتنين الكفار كانوا: النمرود و بُخْتُنصّر.\nوالاتنين المؤمنين كانوا : ذو القرنين وسليمان بن داود عليهما السلام.\nوإذا أراد الله شيئا هيأ أسبابه\nفاكرين بني إسرائيل عملوا إيه في سنحاريب وبختنصر من كم سنة فاتت وذلوهم إزاي\nلما بنو إسرائيل عصوا أمر الله وطغوا في الأرض وبدأوا يقتلوا الأنبياء، ربنا ألقى في قلب بُخْتُنصّر إنه يروح يغزو بني إسرائيل مرة ثانية\nفاتحرك بالجيش بتاعه في اتجاه بيت المقدس.. ففي الطريق لما وصل لدمشق، أهل دمشق خافوا منه، فقدموا له الهدايا والأموال واتصالحوا معاه، \nفتركهم بُخْتُنصّر واتجه لبيت المقدس، فمَلِك بني إسرائيل في الزمن ده اتعاهد مع بُخْتُنصّر برده بنفس الطريقة زي ما أهل دمشق عملوا معاه،\nوأخد بختنصر بعض أثرياء بني إسرائيل معاه، وقرر إنه يرجع للعراق..\nفساعتها بنو إسرائيل اعترضوا على ملكهم وإللي عمله ده وغضبوا إنه إزاي يعمل كده.. فراحوا قاتلينه ونقضوا الصلح مع بُخْتُنصّر\nفبختنصر رجعلهم تاني وحاصر مدينة القدس فترة، فلما طال الحصار استسلموا لبختنصر، وفتحوا أبواب المدينة..\nدخل بختنصر المدينة وحرَقها وقتل المقاتلين وسبى النساء والأطفال، وحرَّق التوراة، وخرَّب الحصون وهدم محاريب العبادة..\nيعني أنزل بيهم العذاب والعقاب إللي فعلا  يستحقوه\n\"وَقَضَيْنَا إِلَىٰ بَنِي إِسْرَائِيلَ فِي الْكِتَابِ لَتُفْسِدُنَّ فِي الْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّا كَبِيرًا\"\nمش بس كده، ده كمان بختنصر أخد معاه إلى أرض العراق ٤٠ ألف من اليهود كعبيد، عشان يخدموا أهل بابل زي ماخدموا الفراعنة في مصر\nوفي بعض اليهود هربوا منه لمصر في الوقت ده.. وبكده انتهى تماااما الحكم اليهودي في فلسطين\nهمّ اليهود هيرجعوا تاني بعدين زي ماهنشوف، لكن مش هيرجعوا كحكام للبلد،\n\"فَإِذَا جَاءَ وَعْدُ أُولَاهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَا أُولِي بَأْسٍ شَدِيدٍ فَجَاسُوا خِلَالَ الدِّيَارِ ۚ وَكَانَ وَعْدًا مَّفْعُولًا \"\n☆فكان العلو الأول لبني إسرائيل\n في زمن داود وسليمان عليهما السلام.. \nفلما كفروا وطغوا وأفسدوا، ربنا أرسل عليهم إللي يهلكهم ويذلهم، إللي هو بختنصر وجنوده،\nإللي هي: \"بَعَثْنَا عَلَيْكُمْ عِبَادًا لَّنَا أُولِي بَأْسٍ شَدِيدٍ فَجَاسُوا خِلَالَ الدِّيَارِ \"\nوأي حد سواء مسلم أو كافر فهو عبد لله غصب عنه\nوبالنسبة للعُلو الثاني، فلعله يكون هو إللي احنا شايفينه دلوقتي بيحصل لليهود ، في أرض فلسطين وأجزاء من لبنان ومن سوريا،\nبقى ليهم اتصالات إقتصادية على أعلى مستوى في العالم، وبقى في دول كبيرة واقفة معاهم، وبقى ليهم هيبة سياسية ووزن في صناعة القرار على مستوى العالم،\nولسه بيخططوا في التوسع أكتر وأكتر عشان يقيموا دولة إسرائيل الكبرى المزعومة بتاعتهم... وكل ده داخل ضمن العُلو في الأرض ،\n\"ثُمَّ رَدَدْنَا لَكُمُ الْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَاكُم بِأَمْوَالٍ وَبَنِينَ وَجَعَلْنَاكُمْ أَكْثَرَ نَفِيرًا\"\nفاحنا حاليا مستنيين البشارة الثانية إللي جت في الآية بعد كده، إن ربنا يرسل عليهم إللي يعلمهم الأدب تاني ويعيدوا الكرة تاني عليهم، زي ما ربنا قال:\n \"فَإِذَا جَاءَ وَعْدُ الْآخِرَةِ لِيَسُوءُوا وُجُوهَكُمْ وَلِيَدْخُلُوا الْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍ وَلِيُتَبِّرُوا مَا عَلَوْا تَتْبِيرًا\"\nفإذا جاء وعد الآخرة يعني: المرة الثانية \nالمهم،\nكان من ضمن إللي بُخْتُنصّر أسرهم: نبي من أنبياء الله اسمه دانيال..\nفلما مشي بختنصر من مدينة القدس ووصل للعراق بالأسرى، مسك النبي دانيال وحطه في بئر كبير وحط معاه أسدين عشان ياكلوه\nحصل ايه مع النبي دانيال هنعرف دا الجزء الجاي"}, {"n": 31, "l": "الجزء ٤٤ | عزيز ذو القرنين __1 | والجزء ٤٥ | ذو القرنين __2", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_الرابعة_والأربعون\n#قصة_عُزَير\n#مقدمة_عن_ذي_القرنين\nوقفنا المرة إللي فاتت عند بُخْتُنصّر لما أدخل أسدين مع النبي دانيال في بئر كبير عشان ياكلوا ويقتلوه وهو صاحي،\nلكن سبحان الله الأسدين لم يؤذياه بالعكس ده قعدوا يلحسوا فيه\nربنا أيّد نبيه بمعجزة من عنده تُثبت إنه نبي \n☆وطبعا بُخْتُنصّر مش مستوعب ده اسمه إيه إللي حصل ده\nماهو أصله مش فاهم إن كل المخلوقات ماتقدرش تعمل حاجة إلا بأمر ربنا وإن ربنا هو مُسبب الأسباب ومالك الملك يقدر ينزع الأسباب ويعطلها في الوقت إللي يريده،\nميعرفش إنما أمره إذا أراد شيئا أن يقول له كن.. فيكون.. ميعرفش: \n\" إن الأمة لو اجتمعت على أن يضروك بشيء لن يضروك إلا بشيء قد كتبه الله عليك\"\nخرج دانيال من البئر سليم مُعافى\nفعمل خاتم ونقش على الفص بتاعه صورة رجل بين أسدين والأسدين بيلحسوه، عشان مينساش نعمة ربنا عليه بإنه أنقذه في الوقت العصيب ده\nمن ضمن إللي بيُحكَي في قصة النبي دانيال، إن بُخْتُنصّر شاف رؤيا ونسيها، فسأل عنها دانيال،\nفحكاها له دانيال زي ما شافها وفسرها له كمان، وكان تفسيرها بشارة ببعثة رسول الله ﷺ، وإن مُلك أمة التوحيد والإسلام هيبلغ مشارق الأرض ومغاربها\n \n◇قصة دانيال عليه السلام\n من الإسرائيليات التي لا تُصدق ولا تُكذب، \nلكن الصحابة لما فتحوا مدينة تُسْتَر في فتوح فارس،\nودخلوا بيت مال الهُرمُزان إللي هو قائد الجيش الفارسي في معركة القادسية،\nلقوا فيه تابوت، كان جواه جثة لرجل أنفه طولها ذراع، كان أهل الفرس لما ينقطع عنهم المطر كانوا بيستسقوا بجثة الراجل ده،\nفأرسل الصحابة لعمر بن الخطاب رضي الله عنه يحكوا له عن قصة الجثة دي، \nفقال لهم عمر: إن ده جسد نبي لإن الأرض والنار مش بياكلوا أجساد الأنبياء.. \nولما لقوا الخاتم في يده، الصحابة سألوا الناس عنه، فالناس قالوا لهم إن دانيال ده كان ملك من الملوك السابقين أسَره وحصل كذا كذا.. وحكوا لهم حكايته مع الأسدين إللي على الخاتم، \nفعرف الصحابة إنه النبي دانيال..\nوحفر المسلمون ثلاثة عشر قبرا في النهار، \nودفنوا جثة النبي دانيال في واحد منهم بالليل عشان محدش يعرف مكانه ويطلعه تاني، ويحافظوا على التوحيد،\nويُبطلوا عبادة التوسل بالأموات إللي تعتبر شرك بالله تعالى\n☆بالمناسبة :\nمدينة تُسْتَر بالفتح، مع إن معظمنا كان بيمسعها بالضم \"تُستُر\" لكن لما بحثنا عنها بالتشكيل، لقينل الموجود كان بالفتح في تفسير ابن كثير، ومكنش موجود بالضم خالص.. فهل هي ليها تشكيلين ، واحد بالضم وواحد بالفتح؟ الله أعلم\nلكن المؤكد إن التشكيل بالفتح ثابت\nنرجع بقى شوية لبيت المقدس بعد خروج بُخْتُنصّر منه..\nأصبح بيت المقدس خراب والناس مقتولين فيه، فمرّ على بيت المقدس رجل صالح من بني إسرائيل،\nوكان راكب على حمار بتاعه، وكان معاه سلة فيها أكل يخصه.. كان فين ورايح فين؟ محدش يعرف\nلكن المهم إنه لما دخل المدينة وشاف الناس مقتولة والمدينة خراب، قال في نفسه وهو بيتعجب:\nإزاي الناس دي ربنا هيحييها مرة تانية\nهو مكنش بيشك في قدرة ربنا.. لكنه كان مستغرب\n \nهقول لكم زي إيه عشان أقرب لكم المعنى\nعارفين لما تشوفوا إعلان عن شقة هتكون عاملة إزاي بعد التشطيب \nأو عمارة مثلا هتكون عاملة إزاي لما تتبنى وتخلص خالص وشكلها في الإعلان خرافي وشديد الإبهار، \nوانتم على أرض الواقع مجرد شايفين يادوب الأساس هو إللي بيتحفر.. فيبقى فيه تعجب جواكم كده:\nإزاي الناس دول هيعملوا العمارة لحد ما توصل في الآخر بالمنظر ده \nهو انتم هنا معندكوش شك إنها فعلا هتتبنى، لكن انتم بس مستغربين مندهشين متعجبين\nولله المثل الأعلى ...\nأهه ده كان إحساس الرجل الصالح، ويقال إن اسمه أَرميا النبي إللي اتكلمنا عنه المرة إللي فاتت أو إنه اسمه عُزيْر إللي احنا عارفينه من القرآن،\nبس العلماء اختلفوا هل عُزَير ده رجل صالح ولا نبي\nلكن المشهور عند أهل التفسير إنه رجل صالح واسمه عُزَير،\nفلما شاف عُزيْر خراب المدينة وشاف كمية جثث القتلى وشدة المقتلة فيهم، استغرب إزاي ربنا هيرجع الأرض دي عمار مرة تانية\n\"أَوْ كَالَّذِي مَرَّ عَلَىٰ قَرْيَةٍ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْيِي هَٰذِهِ اللَّهُ بَعْدَ مَوْتِهَا\"\nفربنا توفاه لمدة 100 سنة، ثم أحياه من تاني.. وخلال المائة سنة دي أحداث كتيير حصلت...\nبختنصر كان مات خلاص،\nوحصلت معركة بين أهل بابل في العراق وبين الفُرس في إيران، وانتصر الفُرس على البابليين بمساعدة اليهود إللي كانوا في بابل عبيد زي ما قلنا،\nوضم الفُرس حُكم فلسطين للدولة الفارسية، وانتهى الحكم البابلي العراقي لفلسطين، ودخل فيها الحُكم الفارسي..\nوكان بعض اليهود رجعوا لأرض فلسطين في الوقت إللي هي فيه تحت الحكم الفارسي، وبدأوا يعمَّروا المدينة مرة تانية....\nكل ده وعُزير ميت\nفبعد ما المائة سنة خلصوا ربنا بعثه وأحياه من تاني.. فلما قام، كان متخيل إنه نام كام ساعة بس كده،\nفربنا سأله على لسان ملك من الملائكة في هيئة بشر يعني غالبا: انت بقالك أد إيه نايم؟\nرد عُزير : يوم أو جزء من يوم\n.. \n\"قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ\"\nفقال له: انت فاهم غلط، انت بقالك 100 سنة نايم،\n\"قَالَ بَل لَّبِثْتَ مِائَةَ عَامٍ\"\nوعشان تتأكد من كلامي بُص للأكل إللي معاك كده وبص على حمارك،\nويُقال إن كان معاه عنب وتين وعصير،\nفلما بص عليهم لقى كل حاجة زي ماكانت كإن فعلا عدى عليهم كام ساعة فقط زي ما هو نفسه قال، فاستغرب إزاي بتقول 100 سنة ومفيش حاجة اتغيرت\n\"فَانظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ\"\nلكن لما بص على حماره لقاه بقى عضم كإنه فعلا ميت بقاله سنيين طويلة،\nفنادى المَلَك على عظام الحمار فاستجابت وبقت تركب على بعضها لوحدها، وعُزير واقف مذهول إزاي في لحظات المَلَك ألبس العظام بالعروق والأعصاب واللحم وبعدين الجلد لحد ما أحيا الحمار من تاني بإذن الله..\n\"وَانظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ آيَةً لِّلنَّاسِ ۖ وَانظُرْ إِلَى الْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا\"\n\"فَلَمَّا تَبَيَّنَ لَهُ قَالَ أَعْلَمُ أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ\" \nوهو ده \"عينُ القين\" إللي اتكلمنا عنه قبل كده في قصة طلب إبراهيم عليه السلام من ربنا إنه يُريه كيف يُحي الموتى\nركب عُزَير على حماره ومِشي وسط الناس ، فاستغربهم واستغربوه! مين ده! ومين دول!\nكل حاجة متغيرة !... فحاول إنه يخمن مكان بيته، لحد ما وصل عند بيت وكان على باب البيت امرأة عجوز ،\nفسألها ده بيت عُزير؟ فبكت المرأة العجوز وقالت: \nبقالي زمن ماسمِعتش حد بيقول اسم عُزير، الناس هنا كلهم نسيوه خلاص..  \nفقال لها : أنا عُزير ..ربنا أماتني 100 سنة وبعدين بعثني تاني النهاردة، فالمرأة العجوز أخدته وراحت بيه لمجلس بني إسرائيل عشان تقول لهم عنه، والمرأة دي كانت أَمَة من الإماء بتخدم في بيت عُزير من زمان،\nحكت لهم القصة بتاعته، فطبعا بنو إسرائيل مصدقوش كلامها.. \nوكان من ضمن اللي سمعوا الحكاية منها هناك ابن عزير ، فقال: \nإن أبي بين كتفيه شامة سوداء... يعني زي علامة لونها إسود كده ومميزة وأنا عارفها من زمان\nفكشف عُزَير عن كتفه، فشافوا العلامة وعرفوا إنه عزير! \nوكان عُزير أعلم واحد فيهم بالتوراة بعد ما كان حرَّقها وأفناها بُختنصر، \nففرحوا بيه جدا وكان بالنسبة لهم آية عظيمة جدا بالفعل زي ما ربنا كان قال في قصته من شوية \" َلِنَجْعَلَكَ آيَةً لِّلنَّاسِ\".. يعني كل إللي عاش وسطيهم من نفس جيله كلهم عجائز، حتى الأَمَة إللي خدمت في بيته، وحتى ابنه إللي كان أصغر منه،\nكلهم عواجيز إلا هو فقط إللي شاب، على هيئته من يوم ما اختفى\nبني إسرائيل يعملوا إيه بقى\nمش مثلا يزدادوا إيمانا بالله بسبب المعجزة دي..! لأ، ده قالوا : عُزَير ابن الله\n☆يعني إللي في دمهم في دمهم\nلكن الحق يتقال برده، دي كانت طائفة معينة فقط من اليهود إللي قدسوا عُزير وقالوا إنه ابن الله، وكان منهم يهود المدينة إللي كانوا على عهد رسول الله ﷺ، سبحانه وتعالى عما يقولون علوًّا كبيرا.. \nو في الأزمان إللي جت بعد عزير اليهود تبرأت من القول ده،\nلكن في الأصل القول ده كان موجود فيهم ومنشأه كان من عندهم\nإيه إللي حصل لعُزير بعد كده ..وعاش كم سنة...؟\nالله أعلم \nمفيش أخبار عن الموضوع ده؛ لأن زي ماحنا عارفين إن ربنا بيحكي لنا أخبار الأمم السابقة عشان ناخد منها العبرة\nيعني لما نقرأ أي قصة من قصص الأنبياء في القرآن، لازم تسيب أثر في حياتنا بالعبرة إللي أخدناها منها فعلا ،\n ونبدأ على أساسها نتغير للأحسن للي يرضي ربنا عنا،\nوإلا العبر دي كلها هتكون حُجة علينا يوم القيامة بدل ما تكون حجة لنا\nعاش بنو إسرائيل في بيت المقدس تحت الحُكم الفارسي حوالي 207 سنة \n،\nلحد ما غزا القائد الروماني الكبير الإسكندر المقدوني فلسطين، وأزال الحكم الفارسي، وبدأ الحكم الإغريقي في فلسطين... \nوبنو إسرائيل كل الفترات دي محكومين وتابعين لكل الحكام إللي بيحكموا فلسطين\n☆إيه ده\n...معنى كده إن الإسكندر المقدوني ده هو ذو القرنين\nهو في ناس بتخلط بين الاتنين وبتقول إن الإسكندر الأكبر ده هو ذو القرنين\nوالكلام ده غير صحيح .. لإن الإسكندر المقدوني الإغريقي كان كافر بيعبد الأصنام، زيه زي الدولة الفارسية بالضبط\nولكن على الرغم من كفره إلا إنه كان ملك عادل ولعل ده إللي بيخلي الناس تلخط بينهم..\nوفترة حكمه لفلسطين إللي كانت مدتها ٢٦٩ سنة، كان فيها علوم كتير وازدهار في جوانب المعيشة وغيره، بشكل أبهر اليهود إللي كانوا في فلسطين، فبدأوا يتعلموا لغة الإغريق وثقافتهم.. \nوانقسم اليهود لفرقتين: \nالفرقة الأولى: فرقة متأَغرقة، يعني بتتبع الإغريق في كل حاجة حتى الوثنية \n☆يعني مش مثلا ياخدوا الحلو ويسيبوا الوحش، لأ، ده أخدوا كل شيء عن الإغريق\nمش بس يتعلموا ثقافة الإغريق وعلومهم، لأ أخدوا عنهم كمان عبادة الأوثان، وهمّ أصلا أهل كتاب وعندهم الأنبياء،\nومش بس كده بقى، دول حرَّفوا التوراة إللي هي مُحرّفة أصلا من قبل كده عشان توافق ثقافة الإغريق \nآه أومال إيه\nمش لازم يشجعوا تجديد الخطاب الديني زي عندنا كده\n وكإن تجديد الخطاب الديني معناها نسف أعمدة وأركان الدين الأولاني وإقامة بيت جديد على أنقاضه\nيمكن حِجتهم في ده زي حِجة بعض المسلمين في زماننا إللي بيتبعوا الغرب في كل حاجة برده و بيقلدوهم حتى لو كان في أمر فيه مخالفة للعقل والمنطق والفطرة السليمة ، زي مثلا تقليعة لبس الهدوم المقطعة\nأو أمْر فيه مخالفة للدين، زي تقليد أهل الفسق بتوعهم في اللبس والزينة والمُوبقات، وزي إن البنت يكون لها صاحب أو الولد يكون له صاحبة\nومتخيلين إن هو ده التقدم والحضارة لإن دي أفعال نقلوها من بلاد متحضرة ومتقدمة في النواحي المعيشية والعلمية،\nفبقوا متخيلين إن تقليد أي شيء غربي حتى استعمال الكلمات باللغات الأجنبية في الحوار اليومي العادي ده كده بقى عنوان الرقي والتحضر\nليه أنا كمسلم ربنا أكرمني بالإسلام، آخد كل حياة الكافر بكل إللي فيها و أخلّي حياتي نسخة منها\n☆عارفين..معلومة كده عالسريع..\nفي القرون الوسطى، أوروبا كانت في أشد عصور جهلها،\nفي حين إن المسلمين في الأندلس كانوا في قمة حضارتهم في كافة مناحي الحياة.. لدرجة إن أبناء ملوك أوروبا كانوا بييجوا يتعلموا في جامعة قرطبة،\nوكان الأمراء بيدخّلوا كلمات باللغة العربية وسط كلامهم عشان يتفاخروا بإنهم يعرفوا اللغة بتاعة أكثر ناس على وش الأرض عندهم حضارة في الزمن ده، إللي همّ المسلمين\nأهه ده إللي بيحصل لكل أمة مهمزومة مبهورة بأي أمة أقوى منها\nفاحنا المفروض نفصل بين الحلو والوحش، والحرام والحلال، \nنترك الأمور الخبيثة المخالفة للدين والفطرة والعقل،\nوعادي مفيش مشكلة نستفيد بالأمور الطيبة من عندهم مادام مش بتخالف ديننا،\nحتى في حديث بيُروَى عن رسول الله ﷺ بيقول فيه:\n\"الْكَلِمَةُ الْحِكْمَةُ ضَالَّةُ الْمُؤْمِنِ فَحَيْثُ وَجَدَهَا فَهُوَ أَحَقُّ بِهَا\"\nهو أه الحديث ضعيف لكن معناه صحيح \nالمهم ده كان حال الفرقة الأولى المتأغرقة...\nالفرقة الثانية بقى: هي إللي فضلت على التوراة المُحرفة التحريف العادي\n◇التوارة اتحرفت لأنها اتكتبت بعد موت موسى عليه السلام بسبعمائة سنة \nفقعدوا يجيبوا كلمة من هنا على كلمة من هنا...واحنا شفنا أصلا أخلاق بني إسرائيل كانت عاملة إزاي\nفكانوا يزوّدوا وينقصوا باللي يوافق هواهم،\nوكانوا بدأوا بكتابة التوراة لما راحوا العراق أسرى وكان بختنصر حرق لهم التوراة زي ما قلنا المرة إللي فاتت،\nوكان قائد الفرقة التانية دي واحد اسمه \"يًهُوذا المُكابِي\"، واليهود بيعتبروه بطل لإنه ثبت واتمسّك بالتوارة –المحرفة قديما أصلا- في ظل اتِّباع معظم باقي اليهود في أرض فلسطين للإغريق والتوراة المحرفة حديثا\nاستمر حكم الإغريق ٢٦٩ سنة زي ما قلنا لحد ما في دولة كبيرة جدا في الوقت ده وهي الدولة الرومانية غزت فلسطين ودخلت فيها وحكمتها وحكمت اليهود إللي فيها،\nوكان اليهود من أيام ما ساعدوا الفُرس وهم عندهم زي حُكم ذاتي كده\nلكن لما الدولة الرومانية غزت فلسطين قضت على الحكم الذاتي بتاع اليهود ده، وأصبح اليهود تابعين لحكم الدولة الرومانية\nبعد حوالي ثلاثين سنة، دخل في اليهودية زعيم من الزعماء الرومان اسمه \"هيرُودِس\"،\nوالزعيم ده كان ظالم وفاسد وشديد البطش بسكان فلسطين بما فيهم اليهود، وكان الجميع بيكرهوه\nلكن من أعماله إنه جدد بناء المسجد الأقصى ووسّعه..\nوكان هيرودس حاكم لفلسطين في زمن زكريا ويحيى عليهما السلام إللي هنعرف قصتهم إن شاء الله بعد ما نتكلم عن بعض قصص حصلت في بني إسرائيل قبل زكريا عليه السلام\nطيب إيه حكاية ذي القرنين بقى\nده إللي هنعرفه الجزء الجاي إن شاء الله \n#قصص_الأنبياء\n#الحلقة_الخامسة_والأربعون\n#ذو_القرنين\nوقفنا المرة إللي فاتت عند سؤال : مين هو ذو القرنين\nقلنا قبل كده إن في أربعة حكموا الأرض، أولهم كان النمرود.. والثاني هو ذو القرنين.\nذو القرنين كان عبد صالح مسلم موحد لله، يُقال إنه أسلم مع إبراهيم عليه السلام وطاف بالكعبة مع إبراهيم وإسماعيل، لكن مفيش دليل على كده، ده اجتهاد لبعض المفسرين، وبالتالي احنا مانعرفش زمنه إيه بالتحديد، إللي يهمنا من قصته العبرة \nكان سبب ذكر قصة ذو القرنين في القرآن إن مُشركي مكة كانوا عايزين يتأكدوا إن محمد ﷺ رسول من عند ربنا فعلا ولّا لأ، فقالوا: خلونا نسأل اليهود ..\nفراحوا لليهود في المدينة وسألوهم: نعرف إزاي إذا كان محمد صادق ولا كاذب\nفاليهود قالوا لهم: اسألوه عن تلات حاجات:\nوكان من ضمن الأسئلة التلاتة: إنهم يسألوه عن مين هو الملك إللي طاف الأرض..\nفراح المشركين يسألوا رسول الله ﷺ ، فقال لهم رسول الله ﷺ إنه هيقول لهم الإجابة بكرة، ونسي يقول إن شاء الله زي ما قبل سليمان عليه السلام نسي يقولها، قبل كده،\nفاكرين\nوكل يوم يقول لهم هقول لكم بكرة وينسى، ورسول الله ﷺ  لا ينطق عن الهوى، يعني ماينفعش يقول لهم عن قصة ذي القرنين أي كلام من عنده كده وخلاص\nلحد ما عدى ١٥ يوم -وفي رواية تانية شهر- ونزل القرآن يوضح مين هو الملك ده في سورة الكهف.. \nونزلت الآية تعاتب النبي ﷺ على نسيانه قول إن شاء الله: \"وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَٰلِكَ غَدًا *إِلَّا أَن يَشَاءَ اللَّهُ\"\nوطبعا واحد طاف الأرض كلها يعني قابل ناس كتير وحصل معاه أحداث كتير، فعشان ربنا يحكي لنا عنه كل حاجة هنحتاج لأجزاء كتيرة ومجلدات \nفربنا قالنا بس جزء من رحلته باللي يفيدنا وناخد منه العبرة \n\"وَيَسْأَلُونَكَ عَنْ ذِي الْقَرْنَيْنِ قُلْ سَأَتْلُو عَلَيْكُمْ مِنْهُ ذِكْرًا\"\nطيب هو ذو القرنين اسمه الحقيقي إيه؟\n واشمعنى يعني لقبه كان ذو القرنين بالذات؟\nطيب وبلده الأصلي كان إيه؟...واتولد سنة كام...و...و...و؟ \nكل الحاجات دي اختلف فيها العلماء وزي ما قلنا مش هتفيدنا في حاجة... هي من باب : علمٌ لا ينفع وجهلٌ لا يَضر\n☆ودي من ضمن العبر إللي في قصته:\nإننا نتعلم مانسألش ولا ندوّر إلا عن الحاجة إللي هتفيدنا في ديننا وحياتنا.. \nعود نفسك في حياتك قبل ما تسأل عن حاجة في أمور الدنيا أو أمور الدين المسكوت عنها، تسأل نفسك سؤال: \nهستفيد إيه لو عرفت\nوده هيمنع عنك شر كتير جدا وهيمنع عنك تضييع أوقات وطاقات انت محتاج لها أكتر\nولعل أهم فايدة هنستفيدها، إننا نجنب نفسنا إننا نتكلم فيما لا يعنينا، وهنكون وصلنا لمحاسن الإسلام وكمال الإيمان؛ لأن من حسن إسلام المرء تركه ما لايعنيه\nفاللي يهمنا نعرفه إن ذا القرنين كان ملك مسلم طائع لله،\nربنا مَكِّن لذي القرنين في الأرض وأعطى له مُلك عظيم ووهبه من كل شيء من كل شيء علم،\nيعني وهبَه من كل علم وسيلة وطريقة يقدر يحقق بيها إللي هو عايزه،\n\"إِنَّا مَكَّنَّا لَهُ فِي الْأَرْضِ وَآتَيْنَاهُ مِنْ كُلِّ شَيْءٍ سَبَبًا \"\nيعني مثلا كان عنده ناس مترجمين بيتكلموا بلغات متعددة لأهل الأرض، لما يروح أي بلد يدعوا أهله للإسلام كان بيدعو الناس عن طريق المترجمين دول،\nفذو القرنين كان هدفه المحدد هو نشر دين الله في الأرض وإقامة العدل بين الناس،\nوبالرغم بقى من إن ربنا أعطى له علم عن كل حاجة فهو موقفش...منمش في الخط يعني\nربنا إداله بداية العلم وهو يطور ويتعمق أكثر لحد ما يُتقن العلم ده، وهو ده معنى:\n\"فَأَتْبَعَ سَبَبًا\"\nعارفين زي إيه في حياتنا دلوقتي؟\nزي الإلتزام بالدين\nربنا ميسر لنا أسباب إننا نتعلم ديننا الصحيح واحنا على سريرنا في أوضة نومنا في التكييف وأكل وشرب رايح جاي، سواء عن طريق مقالات أو كتب إسلامية موجودة عالنت أو محاضرات عاليوتيوب أو...أو...أو ..\nوهو ده السبب إللي ربنا أعطاه لنا زي ما أعطى ذا القرنين،\nاحنا بقى بنعمل إيه إلا من رحم الله\nتلاقي مثلا إللي يقولك أصل الكلام كتير وانا مبحبش أقرأ الكلام الكتير، مع إنه تلاقيه عند الروايات الطويلة منشار قراية عادي جدا\nتلاقي حد تاني يقولك أصل مفيش وقت، وهو بيضيع معظم يومه على فيسبوك وغيره\nتلاقي حد تالت يقول لك أصل انا مبحبش أقعد كده وأقعد أسمع وبس...بحب الحوار والتفاعل كده،\nلازم حد يتكلم معايا وجها لوجه عشان المعلومة تدخل... وحد رابع... وخامس....  \nوندّي بقى ضهرنا للوسائل إللي ربنا يسرهالنا للخير، ونقعد نشتكي ونسأل احنا ليه متأخرين كده وليه فاشلين وليه حاسين بالإحباط والهزيمة وكده\nأهه هو ده الفرق بينا وبين ذو القرنين ..هو انتهز الفرص والنعم إللي ربنا أعطاها له وإحنا لأ\nفلما ربنا يعطيك فرصة وسبب ووسيلة ميُسرة إوعى تفرط فيها...إوعى تتلكع..\nلقيت ربنا فتح عليك سبب وباب إنك تتعلم دينك، أتبِع سَبَبًا... ادخل كمان واتعمق فيه لحد ما توصل لفوايده وكنوزه إللي تنفعك في حياتك وآخرتك..  \nلقيت سبب وباب إنك توجع أعداء الله.. كمل وأتبِع سببا.. \nوإوعي تكسل أو تأجل، لإنك ماتعرفش إمتى ربنا ممكن يسحب منك الوسيلة دي أو السبب والفرصة دي\nحتى في العبادة.. لقيت نفسك ونشاطك وهمتك زايدة في قراءة القرآن، اقرأ ...ثم اقرأ...ثم اقرأ... \nلقيت نفسك وهمتك في الصلاة، صلي .. وصلي.. وصلي... لقيت نفسك في مساعدة الناس ساعد على أد ما تقدر. ..\nمن الآخر: لما ربنا يديك فرصة لزيادة الحسنات، سواء علم أو تطبيق للعلم ده، امسك فيها بإيدك وسنانك\nودي بتكون من علامات حب وقبول ربنا للعبد وسعيه.. إنه يفتح له أبواب الخير وييسرها له ويزيده منها ويعينه عليها \nفكل ما هتستغل الفرصة ربنا هيبعت لك فرصة تانية وتالتة وعاشرة، وهيفتحلك أبواب الخير ورا بعضها\n☆وده يدخّلنا في نقطة تانية مهمة\nوهي إن في ناس تسيب أبواب الخير إللي ربنا فاتحهالها بالفعل، وتروح تدوّر على أبواب الخير المقفولة في وشها، وتفضل واقفة قصادها تحاول تفتح فيها ومستنية تتفتح\n طيب متسيبوا المقفول ومتنشغلوش بيه، واشتغلوا على المفتوح قصادكم دلوقتي\nمثلا يعني:\n◇شباب يقعدوا يقولوا عايزين نروح نحرر المسجد الأقصى والجهاد ذروة سنام الإسلام و...و...\nطيب دي مقفولة دلوقتي لسببب أو لآخر، نعمل إيه بقى\n نفضل من غير سعي خالص يعني؟ \nلأ، احنا نشتغل على نشر الوعي بالقضية وتصحيح مفاهيم الناس عن العقيدة والطاعات وأسباب النصر والهزيمة والإعداد، لحد ما الباب يتفتح\n◇واحدة مثلا عايزة تنزل تروح دار لتحفيظ القرآن وتتعلم العلم الشرعي وأبوها ولّا زوجها مش موافقين...\nالسكة دي مقفولة طب تعمل إيه\nتوقف السعي خالص؟\n لأ، تحاول تشوف سكة تانية، مثلا معلمة من على النت تحفظ معاها وتسمع الدروس العلمية\n◇واحد عايز يشتغل في مجال دعوة الأجانب غير المسلمين للإسلام، ومعندوش الإمكانيات دلوقتي لا لتعلم اللغات ولا للتواصل معاهم أصلا! يسيب الدعوة خالص؟\nما هو عنده باب دعوة المسلمين في جامعته أو مدرسته أو الحي بتاعه أو قرايبه مفتوح، ليه يسيب الباب المفتوح ويفضل منتظر المقفول يفتح\nالمشكلة إن الناس بقت بتيجي عند المقفول وتركب دماغها، وهي دي يعني هي دي \nلكن ذو القرنين مكنش زي الناس دي،\n\"آتيناه من كل شيء سببا...فأتبع سببا...\" بس كده.. خِلصت\nذو القرنين بقى ماشي يطوف في الأرض...\nأول مكان وصل له ذو القرنين كان عند مغرب الشمس... مكان كده لقى عنده بحر فشاف هناك الشمس بتغرب ورا البحر وكإنها بتغرق جوة البحر نفسه يعني،\nزي لما وقت الغروب بنبقى قاعدين على البحر وبنحس كإن الشمس بتغطس جوة البحر زي كده تقريبا\nوفي المكان ده كان لقى ناس وكانوا كفار وظلمة..\n\"حَتَّى إِذَا بَلَغَ مَغْرِبَ الشَّمْسِ وَجَدَهَا تَغْرُبُ فِي عَيْنٍ حَمِئَةٍ وَوَجَدَ عِنْدَهَا قَوْمًا \"\nفربنا قال لذي القرنين=عن طريق ملك من الملائكة مثلا=\nإن الأمر متروك لك تختار بنفسك تحكم فيهم بإيه ، سواء هتعفو عنهم بدون عقاب، أو هتعذبهم عقابا على كفرهم وظلمهم، فالقرار يرجعلك انت.\n\"قُلْنَا يَا ذَا الْقَرْنَيْنِ إِمَّا أَنْ تُعَذِّبَ وَإِمَّا أَنْ تَتَّخِذَ فِيهِمْ حُسْنًا\"\n☆في مقولة بتقول إيه: إذا دَعَتْك قدرتكُ لظلم الناس، فتذكر قدرة الله عليك\nربنا أعطى القوة والقدرة لذي القرنين وتركه يحكم فيهم بنفسه.. \nزي بالضبط لما ربنا بيعطي الأم القدرة والقوة وترك لها مسؤولية الأبناء، وهمّ ضعاف بطبيعة الحال، \nفلما الأم تتعصب عليهم مثلا في مرة بدون 《وجه حق》 فتضربهم أو تؤذيهم وتتحكم فيهم بدون داعي وتقول هو كده\nهتلاقي زوجها برده إللي ربنا إداله القوة والقدرة هو كمان وترك له مسؤولية زوجته في رقبته، يقوم يتعصب عليها ويقول لها مفيش خروج.. مفيش أكل... مفيش كلام .. \nوكله سلف ودين، لإن الديان عز وجل لا يموت، \nفكما تدين تُدان\nفدلوقتي ذو القرنين ربنا أعطاله القوة والقدرة إنه يعمل في الناس دي إللي هو عايزه،\nفهو وقف وبدأ يفكر، لو أنا في وسطهم كنت أحب يتعمل فيّ أنا إيه؟.. فقرر إنه هيحكم بالعدل..\nيعني الظالم يتجازى على ظلمه في الدنيا بقدر المستطاع، ولو مات ربنا هيحاسبه يوم القيامة على الأفعال إللي لسه ما اتعاقبش عليها، \nقَالَ أَمَّا مَنْ ظَلَمَ فَسَوْفَ نُعَذِّبُهُ ثُمَّ يُرَدُّ إِلَى رَبِّهِ فَيُعَذِّبُهُ عَذَابًا نُكْرًا\"\nوإللي يتوب ويرجع ويُؤمن بالله هنكرمه ونوسع عليه وهنتكلم قصاد الناس عنه بشكل طيب وهنعامله بكل رفق ولين، ولو مات فله الجنة عند ربنا\n\"وَأَمَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَلَهُ جَزَاءً الْحُسْنَى وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا\"\n☆العدل هو أساس استقرار ودوام أي ملك.. حتى مملكة الأسرة الصغيرة خالص دي،\nلو في عدل في البيت بين الأبناء وبين الزوج والزوجة، هيكون في أمان، والأمان بيجيب استقرار \nمسمعتوش عن ناس كفار علاقتهم الزوجية بتستمر سنين طويلة مع إنهم كفار؟\nومسلمين بيوتهم بتتهد من أول كام شهر، مع إنهم مسلمين؟\nلو بحثتم هتلاقوا إن السبب الرئيسي هو غياب العدل.. \nهتلاقي الزوج بيظلم زوجته وهتلاقي الزوجة يا إما بتستسلم للظلم لإنها مش قادرة تصده فبتيجي على نفسها وبتتحول مع الوقت لشبح إنسان عايش ميت دبلانة ومطفية وكلها حزن،\nلا عارفة تربي ولادها، ولا ولادها حاسين بالأمان أو الدفء الأسري،\nأو هتلاقي الزوجة بالعكس، ترد الظلم بظلم أكبر وتتسع دايرة الظلم أكتر وبرده الولاد يغيب عنهم الأمان أكتر وأكتر..\nلكن لو في عدل، هتلاقي الأمان اتوجد... والحب اتولد.. فلو في عدل هيكون في استقرار وإنجازات...\nعشان كده ربنا وضع لنا قاعدة أساسية في حياتنا عشان نؤسس للعدل سواء في الدولة أو حتى في البيوت قال لنا:\nلو اختلفتم في شيء رجعوه لحكم الله ورسوله والحكم يمشي على الكل\n\"فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا \"\nلو طبقنا كلنا القاعدة دي في تعاملاتنا مع أصحابنا ومع أهلنا، حياتنا هتكون مستقرة جدا بإذن الله...\nفاحنا عندنا الدواء بس مين يشربه\nبعد ما ذو القرنين خلص مهمته في القرية إللي كانت عند مغرب الشمس ، اتحرك عشان يشوف باب تاني من أبواب الخير المفتوحة\n \"ثُمَّ أَتْبَعَ سَبَبًا\"...\nذو القرنين موقفش عند رحلة المغرب ولا قال كفاية الإنجاز العظيم إللي أنا عملته ده مش هكمل بقى وخلاص على كده، \nلأ، انطلق بالأسباب اللي ربنا وهبها له يكمل إنجازات و يدوّر على موضع تاني أو باب تاني من أبواب الخير.. \n\"ثُمَّ أَتْبَعَ سَبَبًا\".. \nاتجه في رحلة ثانية جهة مَطلِع الشمس،\nخلال رحلة ذو القرنين من المغرب للمشرق أكيد حصلت أحداث تانية، لكن زي ما قلنا هنركز على إللي ربنا أخبرنا بيه في القرآن عشان ده المهم إللي فيه العبرة\nوصل ذو القرنين لمطلع الشمس، فلقى الشمس بتطلع على قوم عايشين في مكان لا فيه شجر ولا جبال ولا حتى بيوت يعيشوا فيها ، ومش كده وبس،  ده حتى ماعندهمش ملابس يلبسوها تحميهم من الشمس،\n\"حَتَّى إِذَا بَلَغَ مَطْلِعَ الشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَى قَوْمٍ لَمْ نَجْعَلْ لَهُمْ مِنْ دُونِهَا سِتْرًا \"\nفكانوا بيدخلوا في سراديب تحت الأرض أو يدخلوا في المية لحد ما الشمس تغرب وبعدين يمارسوا حياتهم،\nفلما شافهم تعجب من حالهم جدا وإزاي عايشين كده\nفعمل معاهم زي ما عمل مع القوم عند مغرب الشمس،\nوطبعا هو معاه جيشه ومعاه المترجمين، \nفبدأوا يعلموا الناس هناك ثقافة الأغراض الواقية من أشعة الشمس، زي البيوت وظلال الأشجار والمظلات مثلا والملابس وهكذا،\nيعني علمهم إزاي يستتروا من حر الشمس بدل ما بيضطروا ينزلوا في السراديب وفي البحر لحد ما الشمس تغرب،\nكل ده وربنا محيط بعمله وبما وهبه من قوة وسلطان في كل الرحلات دي.\n \"كَذَلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا \"\n☆وهنا نستفيد إن رسالة ذو القرنين الإنسانية واحدة، ألا وهي العدل بين الخلائق\nالكافر والظالم في قوم المغرب عنده زي الكافر والظالم في قوم المشرق، الاتنين بشر ليهم حقوق وعليهم واجبات، بالمثل.. \nيعني هو مش بيفضَّل حد على حد... مبدأه واحد في العدل بين الناس وإعطاء كل واحد إللي يستحقه ومحتاجله\nخلّص مع قوم المشرق وبعدين كمّل..موقفش.. راح يدور على باب تاني من أبواب الخير يفَعّل فيه الأسباب اللي ربنا وهبها له\nوصل في رحلته لمكان بين جبلين أو سدين معينين ...ثغرة...حتة فاضية بين جبلين...زي المثلث إللي\nمالوش قاعدة كده《  \\/  》لقى في المكان ده ناس مش فاهمين أي لغة غير اللغة بتاعتهم همّ بس، بسب بُعدهم عن الناس في المكان البعيد ده،\n\"حَتَّى إِذَا بَلَغَ بَيْنَ السَّدَّيْنِ وَجَدَ مِنْ دُونِهِمَا قَوْمًا لَا يَكَادُونَ يَفْقَهُونَ قَوْلًا\"\nوذو القرنين معاه مترجمين، لكن مفيش ولا مترجم واحد فيهم فاهم من الناس دي أي حاجة\nفيُقال إنهم احتاجوا سبعين مترجم عشان ذو القرنين يفهم هم عايزين إيه\n☆عارفين زي إيه\nلما مثلا أنا أكون بتكلم عربي وواحد تاني بيتكلم أُرْدو وأنا مش فاهمة الكلام..فنسأل في حد يقدر يترجم يا جماعة فييجي واحد ياباني يترجم الأْردو للياباني وأنا لسه مش فاهمة\nفييجي واحد فرنسي يعرف ياباني فيترجم من اليابانية للفرنسية، وبعدين واحد يترجم من الفرنسية للإنجليزية وبعدين في الآخر يترجم من الإنجليزية للعربية وأنا أفهم،\nفاحنا احتاجنا ثلاثة مترجمين عشان أفهم الكلام إللي بالأُردو ،\nفالقوم إللي كانوا عند السد كانت لغتهم غريبة محدش يعرفها،\nفكل واحد من المترجمين قعد يجمّع كلمة من هنا على كلمة من هنا على شوية إشارات لحد ما وصل المعنى لذي القرنين.\nالناس دي كانوا عايزين إيه بقى من ذي القرنين وإللي خلاهم يصمموا إنهم يوصلوا له كلامهم\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 32, "l": "الجزء ٤٦ | يأجوج ومأجوج", "u": "", "t": "#قصص_الأنبياء\n#الحلقة_السادسة_والأربعون\n#يأجوج_ومأجوج\nوقفنا المرة إللي فاتت عند الناس إللي مكنوش عارفين ولا لغة غير لغتهم ولكن صمموا إنهم يوصلوا رسالتهم لذي القرنين،\nكانت إيه رسالتهم بقى \nقالوا: \nيا ذا القرنين إن يأجوج ومأجوج قوم مفسدون في الأرض ...بيقتلوا ويظلموا ويخرّبوا كل حاجة يشوفوها\nفاحنا عايزين منك خدمة، وهي إنك تجعل بينا وبينهم سد عشان ميخرجوش علينا ويفسدوا علينا معيشتنا...ومتخفش إحنا هنديك أجر كبير مقابل مساعدتك لنا\n\"قَالُوا يَا ذَا الْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَى أَنْ تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّا \"\n☆السؤال هنا ..إيه إللي خلى الناس دي تطلب من ذي القرنين طلب زي ده أول ما قابلوه وهم ميعرفهوش...مش ممكن يكون ملك ظالم جاي يقتلهم وخصوصا إنه داخل عليهم بجيشه الجرار ومعاه معداته وآلاته\nالسبب في كده هو نفس السبب إللي خلّى أصحاب يوسف عليه السلام في السجن يحكوا له عن رؤيتهم... \nسّمْت الصلاح الظاهر عليه هو السبب\nماهو الناس الصالحين بيبان عليهم.. بيبان على شكلهم وعلى تصرفاتهم\nمش ساعات تشوف واحد ولّا واحدة تحس إنه صالح وإنه شخص قريب من ربنا؟ \nمع إن دي حاجة قلبية غيبية منعرفهاش ولا يعلمها يقينا إلا الله، بس شكله بيقول كده سبحان الله... تصرفاته وكلامه بيقولوا كده\nعارفين في حديث لرسول الله ﷺ  بيقول:\n\"أَلا أُخْبِركم بِخيَارِكم ؟ الصحابة قالوا : بلى يا رسول الله.\nقال: الذين إذا رُؤُوا ذُكرَ الله\"\n◇هل لما النساء بيشوفوا لبسك كمسلمة، بيذكروا الله ويتمنوا يلبسوا زيك؟... ولّا بيسألوكِ عن لبسك وشياكته وألوانه وجبتيه منين وبكام عشان يقلدوكِ؟\n◇هل لما الناس بيشوفوا تصرفاتكم ويسمعوا كلامكم، بيذكروا ربنا وبيتمنوا إنهم يكونوا في أخلاقكم ودينكم؟\n◇هل لما بيدخلوا على صفحاتكم الشخصية في الفيسبوك مثلا أو يقرأوا كتاب من تأليفكم، بيذكروا ربنا وبيبدأوا يسألوا في الدين وإزاي نقرب من ربنا،\nولّا بيذكروا المسلسل الفلاني ولا الفيلم العلاني ويسألوكم عن قصة شعركم دي بتاعة أنهي فنان أو أنهي لاعب كورة؟\nأهو ده السّمت إللي بنتكلم عليه...\nإن ظاهرك إللي يدل على تقوى وحياء وحسن خلق يخلي الناس يفتكروا ربنا\n¤ملحوظة بقى قبل ما كلامي يتفهم غلط\nكلامنا هنا عن الغالب الأعم، لكن طبعا دي مش قاعدة إن كل حد ظاهره الصلاح بيكون صالح بالفعل..\nفيه ناس بتعرف تتلون وتستعمل وسائل للنصب على الناس باسم الدين..\nوفيه نساء لابسة إسود في إسود ولا يفقهوا في الدين شيء مثلا...\nفي بنات مش محجبة ومتعمقين جدا في الدين ويمكن يكونوا حافظين للقرآن.. \nوممكن المنتقبة إسود في إسود دي ربنا يختم لها بخاتمة سيئة، وحصلت بالفعل وكانت داعية كمان للأسف ربنا يرحمها\nوفي بنت أو شاب ممكن يكونوا ضايعين خالص وفي آخر لحظة في حياتهم ربنا يختم لهم بخاتمة حسنة..\nأيوة برده بيحصل\nلكن مش ده إللي بتكلم فيه نهائي\nدي حالات شاذة ما اقدرش أحطها عشان أطلع منها قاعدة عامة أقيسها على البشر كلهم\nلإننا بكل بساطة: مالناش غير الظاهر.. أحكم على الظاهر الواضح، لحد ما يتبين لي من سريرة الشخص ده إللي لسه مش واضحة، عكس الظاهر الواضح بتاعه ده\nومش أنا إللي بقول كده ده رسول الله ﷺ إللي بيقول\nقال رسول الله ﷺ : \n\"لا تُصاحب إلا مؤمنا ولا يأكل طعامك إلا تقي\"\nإزاي هعرف إن اللي قصادي ده مؤمن ولّا تقي ودي حاجة قلبية لا يعلمها إلا الله\nبكلامه وتصرفاته، يعني من الظاهر \nثم ده الغالب زي ما بنقول لإن رسول الله ﷺ قال :\n\"ألا إن في الجسد مُضغة إذا صَلُحَت صَلُح الجسد كله وإذا فسدت فسد الجسد كله ألا وهي القلب\"، \nويوم القيامة العبرة بالقلوب :\n\" يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ * إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ \"\nفلو القلب في الدنيا سليم، الطبيعي إنه يظهر أثر سلامته دي من الأمراض والشرك على الجوارح، وهيبان في الشكل والتصرفات\n☆ممكن واحدة تقول طيب ماهو ناس بيكون ظاهرها كويس ولما تعاشريها يتبين لك إنها مثلا نقاب على الفاضي ولا لحية على الفاضي أو مظهر متدين عالفاضي وبيعملوا الغلط\nطيب إيه رأيكم بقى إن ده مش ذنبهم\nالمشكلة مش في الملتحي ولا في المنتقبة ولا أي حد عليه مظهر من مظاهر الإلتزام... المشكلة فينا إحنا\nاحنا متصورين إن الناس دي ملايكة بقى ومبيغلطوش،\nفلما يعمل حاجة نقول أاااه شوف الملتحي\n \nشوف المنتقبة\nاحنا اللي ربطنا اللحية والنقاب بالإلتزام 《الملائكي》 ودي مجرد شريعة زي باقي شرائع الإسلام\nواحد ولّا واحدة فيهم كل العِبر بس قدروا ينفذوا حاجة في الدين هياخدوا عليها حسنات فاحنا نقول: \nلأ احلق لحيتك،\nوانتِ اقلعي نقابك وخمارك.. يعني زوّدوا كمان معصية لمعاصيكم أو قللوا الحسنات بتاعتكم\nالحسابات عند ربنا غير حسابتنا خاالص\nلو الإنسان عمل حسنة وزنها زي وزن حبة الخردل ربنا هيجازيه عليها\n\"إِنَّهَا إِن تَكُ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ فَتَكُن فِي صَخْرَةٍ أَوْ فِي السَّمَاوَاتِ أَوْ فِي الْأَرْضِ يَأْتِ بِهَا اللَّهُ \"\nفاللحية ملهاش ذنب ولا النقاب ليه ذنب،\nالملتحي أو المنتقبة أيوة لازم يكونوا قدوة لأن العين عليهم بالذات،\nبس معلش لا النقاب ولا اللحية عبارة عن أجنحة ملايكة الناس بتلبسها فبتكون معصومة\nوعلى فكرة كان في عهد الصحابة من زنى ومن شرب الخمر وكانوا ملتحين...فاحنا إللي محتاجين نغير مفاهمينا \n☆عارفين لو بعد الشرح ده كله \n حد فهم كلامي غلط هعمل فيه إيه\nنرجع بقى لذو القرنين،\nلما كان سَمْت ذو القرنين من الصالحين الناس طلبوا منه المساعدة، وعشان يضمنوا إنه ميرفضش عرضوا عليه الأموال كأجر،\nوطبعا ذو القرنين مش محتاج أي أموال، ده مَلَك شرق الأرض ومغربها\nفقال لهم: مش عايز أجر ولا فلوس، أنا ربنا أعطاني نِعم أعظم من أي أموال\n\"قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ \"\nوده نفس كلام سليمان عليه السلام لملكة سبأ فاكرين\n لما قال للرسول بتاعها :\n\" \"فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِّمَّا آتَاكُم \"\nفذو القرنين قال أنا مش عايز فلوسكم، أنا عايزكم انتم نفسكم.. عايزكم تشتغلوا معايا في بناء السد المنيع ده\n\"فَأَعِينُونِي بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا \"\nوهو ده الإنسان الصادق المخلص إللي عنده مروءة\nمش ييجي ياخد فلوس عشان يساعدك، لأ يستعفف عن أجر مساعدتك وكمان يعلمك ويخليك تدافع عن نفسك بنفسك، \nزي ما المثل بيقول : لا تُعطني سمكة ولكن علمني كيف أصطادها\n☆طبعا ده غير إللي ياخد فلوسك وميساعدكش زي ما طلبت أصلا \n! ما علينا\n!\nعارفين زي إيه مثلا من الواقع بتاعنا\nلما يكون حد فينا عايز يلتزم وعنده مشاكل كثيرة ومش عارف يبدأ منين، \nفندوّر على حد يحل لنا مشاكلنا من غير ما نكون احنا نفسنا طرف في الحل،\nمثلا حد يقول مش عارف أصحى أصلي الفجر \nفنقول طيب نام بدري واظبط المنبه وقول الأذكار وادعي ربنا،\nفهو يسيب 《كل ده》 ويقول لأ أنا عايز حد يرن عليّ ويصحيني\nطيب فين معالجتك انت للموضوع من طرفك... فين اجتهادك بجانب طلبك لمساعدة الآخرين؟..مفيش\nأو مثلا انت عايز تتعلم علم شرعي وتقول لشيخك مثلا أنا عايزك تاخد بإيدي،\nفيقولك طيب اسمع كذا واقرأ كذا وطبّق الخطوات كذا، تقوم تقول له لأ، أصل أنا مابحبش أسمع دروس،\nأنا عاوز حد يمشي معايا خطوة خطوة كل يوم يفكرني، \nأصل أنا بكسل لما ببقى لوحدي...أصل...أصل....\nمهما الناس ساعدوك، في مرحلة هيبقى مطلوب منك انت الحسم فيها بنفسك بالاستعانة بالله وحده، محدش هيقدر يسقيهالك بالمعلقة،\nالدكتور بيوصف الدواء، لكن إللي بيشرب الدواء هو المريض\nفلازم يكون عندنا ذاتية ونعتمد على نفسنا\nكل النصايح إللي بنقولها هنا في قصص الأنبياء هتفضل مجرد كلام على ورق لحد ما انتم تبدأوا تنفذوها\nعايز تبطل سماع الأغاني والموسيقى والأفلام؟ \nبطل فورا وامسحهم من عندك وانوي التوقف... واطلب من صحابك الصالحين يساعدوك على الثبات. \nعايزة تلبسي حجاب شرعي مظبوط ؟ \nإلبسي حالا واتخلصي من هدومك إللي تغضب ربنا... واطلبي من أخواتك المحترمات يساعدوكِ على الثبات.\nابدأ بنفسك وهتلاقي ربنا بعت لك إللي يساعدك وإللي يوجهك\n\"إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم\"\nليها تفسيرين، وتفسيرها هنا ينطبق على المعنى إللي نقصده تماما\nفذو القرنين قالهم أيوة أنا هبني السد لكن مش هبنيه أنا وجيشي لوحدنا، قوموا اشتغلوا معايا..اتعبوا عشان تلاقوا النتيجة\nبدأ يوجههم...هاتوا قطع الحديد...وعشان هو عارف شغله وعارف إزاي هيبني السد بدأ هو إللي يحط الحديد ويرتبه،\nفبعد ما رص الحديد في الفراغ إللي بين السدين \\:/ قال لهم:\nانفخوا النار في الحديد عشان يسخن فلما سخن قال لهم هاتوا النحاس المذاب عشان أسد الفجوات بين الحديد ويمسك كله في بعضه ويبقى حتة واحدة،\n\"آتُونِي زُبَرَ الْحَدِيدِ حَتَّى إِذَا سَاوَى بَيْنَ الصَّدَفَيْنِ قَالَ انْفُخُوا حَتَّى إِذَا جَعَلَهُ نَارًا قَالَ آتُونِي أُفْرِغْ عَلَيْهِ قِطْرًا\"\nودي حاجة تم اكتشافها في العصر الحديث...إن لما يكونوا عايزين الحديد يكون قوي يضيفوا له النحاس\n◇في هنا عِبرة طيبة: \nذو القرنين عشان هو إللي عارف شغله وعارف إزاي هيبني السد ولسه بيعلمهم من الأول خالص،\nبدأ هو إللي يحط الحديد بنفسه بعد ما طلب منهم يجيبوه، ويعلمهم بنموذج عملي قدامهم يقلدوه في طريقة رصه وترتيبه وتسويته فوق بعض،\nالناس مقالوش بقى اشمعنى احنا إللي نتعب في جمع وشيل الحديد ونجيبه لحد عندك وانت إللي ترصه \nطيب ما تنزل انت كمان تجيب الحديد معانا\nهمّ معملوش كده لأنهم عارفين إن كل واحد له دوره، ودورهم إنهم يجيبوا قطع الحديد، ودوره هو إنه يرص الحديد ويعلمهم ده بنفسه أول مرة\nبعد ما السد اتعمل خلاص ومسك في بعضه بقوة، اتحبس يأجوج ومأجوج ورا منه، ومعرفوش يطلعوا من فوقه ويعدّوا، ومعرفوش حتى يخرموا حتة من السد ويطلعوا منها على أهل البلد..\n\"فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا \"\nطبعا ده إنجاز جديد كبير وعظيم...\nلكن ذو القرنين ماوقفش وبص للسد كده وقال بتكبّر:\n إيه الجمال والعظمة دي! ده شغل مش أي حد يعمله\nلأ، ذو القرنين لم يتكبر، وبكل تواضع وعبودية لله عز وجل قال لما بص للسد والناس المؤذية محبوسين وراه والغلابة عايشين في أمان \n\"قَالَ هَذَا رَحْمَةٌ مِنْ رَبِّي فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ وَكَانَ وَعْدُ رَبِّي حَقًّا\"\nيعني ده رحمة من ربنا، أنا كنت مجرد سبب من أسباب رحمته، سخرني ليكم عشان أمنع عنكم الأذى.. إوعوا تفكروا إن أنا إللي عملت كده.. دي من رحمته بيكم عز وجل\nلكن السد ده مش هيستمر منيع وحصين وقوي وشديد بالشكل ده إلى ما لا نهاية.. لأ.. ده في وقت معين هييجي والسد ده هيتفتح ويأجوج ومأجوج هيخرجوا تاني\nفذو القرنين عمل كذا حاجة هنا: \n◇رجّع الفضل في عمله وفي النعم إللي عنده لله\n◇ علّم الناس إن إللي عمله ليهم ده كان رحمة من ربنا أراد الله لها أن تشملهم فهيأ لها الأسباب.\n◇علّم الناس إنهم يكونوا على حذر برده ميناموش في العسل إلى ما لا نهاية، لأ، يستعدوا لخروجهم في يوم من الأيام بالقوة الكافية للدفاع عن أنفسهم؛ لإن مش كل مرة هيلاقوا إللي يمنع عنهم خطر العدو.\nلكن أكتر حاجة هنا عاوزين نركز عليها، إن ذو القرنين نسب الفضل في عمله والنعم إللي عنده لله عز وجل، \nمش زي ما عمل صاحب الجنتين، إللي دخل جنته وهو مُعجب بيها ومتفاخر، فبقى يقول: مستحيل يحصل أي حاجة للجنتين بتوعي دول\n☆مين صاحب الجنتين ده\nطب مش لما نعرف الأول مين همّ يأجوج ومأجوج دول إللي ذو القرنين قفل عليهم السد وهيخرجوا على الناس تاني في يوم من الأيام\nطيب مين يأجوج ومأجوج دول\n◇يأجوج ومأجوج اسمين لقبيلتين عايشين مع بعض، وهم من نسل آدم عليه السلام وفي نفس الوقت برده من نسل نوح عليه السلام.\nفاكرين لما قلنا إن البشر من أبناء نوح عليه السلام التلاتة : سام وحام ويافث ؟\nسام وحام من ذريتهم العرب واليهود.. بني إسرائيل يعني،\nيافث بقى هو إللي خرج من نسله يأجوج ومأجوج\nيعني همّ من البشر عادي، لا همّ جِن ولا كائنات فضائية من حرب الكواكب ولا الواحد فيهم بينام على ودن ويتغطى بالودن التانية ، ولا أي حاجة من الخرافات إللي بتتقال عنهم دي\nلكنهم انعزلوا عن باقي البشر فترة الطويلة، فأدى انعزالهم ده إنهم يتخلّفوا عن باقي البشر،\nوالدليل على كده إنهم عاشوا بين السدين عادي قبل ما ذو القرنين يقفل عليهم... \nوانعزالهم الطويل ده خلّى مبقاش في لغة تواصل خالص بينهم وبين باقي الناس إللي حواليهم،\nوكمان عاشوا على السرقة والقتل والنهب قبل ما ذو القرنين يقفل عليهم، يعني كل مظاهر الوحشية والإنعزال\nويأجوج ومأجوج غلب عليهم التناسل، يعني بيخلفوا كتير، كل ده خلّاهم أمة مرعبة وكاسحة،\nعندهم أبناء كتير جدا، لدرجة إن ربنا يوم القيامة هيقول لآدم عليه السلام:\n \"يا آدم أَخرج بعثَ النار من ذريتك -يعني أهل النار من البشر- ، فآدم هيسأل ربنا: \nإزاي أخرج بعث النار؟.. فربنا هيقول له من كل ألف، ٩٩٩ في النار وواحد في الجنة\nفالصحابة خافوا\n وقالوا يارسول الله: ومين فينا الواحد ده\n!؟\nفبشرهم رسول الله ﷺ إن الواحد ده منهم والألف من يأجوج ومأجوج.. \nفده يدل إن يأجوج ومأجوج من ذرية آدم عليه السلام وإن أعدادهم كبيرة جدا..\nيعني لما يخرجوا هيشربوا بحيرة طبرية كلها، ودي بحيرة كبيرة جدا على فكرة، يعني حسب الإحصائيات البحيرة دي تكفي سكان بلاد الشام لمدة ثلاثين سنة، إللي همّ عددهم حوالي ثلاثين مليون إنسان،\nفلكم أن تتخيلوا أعداد يأجوج ومأجوج.!\nوهمّ زي ما قلنا، ناس كفرة ظلمة فجرة أقوياء جدا.. محدش من الناس يقدر عليهم \n☆إيه ده\n يعني يأجوج ومأجوج هيدخلوا النار .. ؟!\n طب إزاي وهم مبلغهمش رسالة الإسلام ومقفول عليهم السد\nاحنا عارفين إن ربنا لا يُعذّب أحد إلا لما يُقيم عليه الحُجّة والبيان، وده بيكون سواء في الدنيا عن طريق رسول،\n\"وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا\"\nأو في الآخرة عن طريق الإختبار المباشر من الله عز وجل لأهل الفترة زي ما قلنا قبل كده،\nفأي حد بيموت ولم تبلغه دعوة الإسلام، ربنا هيعامله معاملة أهل الفترة، وهيمتحنه يوم القيامة\nطيب يأجوج ومأجوج؟ \nيأجوج ومأجوج من أهل النار لإنهم كفار ، يعني عارفين إن فيه رب لكنهم كفروا بيه، \nوالدليل على كفرهم إنهم بعد ما يخرجوا من السد ويفسدوا في الأرض، هيرموا بالسهام بتاعتهم ناحية السماء فهترجع السهام دي وعليها دم فهيقولوا ساعتها: \nقهَرْنا مَن في الأرض وعَلَوْنا من في السماء..!\nيعني هم عارفين إن في ربنا، وإنه في السماء، وكفروا به، ومش كفر عادي كمان، لأ ده مقتنعين إنهم أقوى منه سبحانه وتعالى، وقال إيه قتلوه\nوده يدل على إن رسالة التوحيد وصلت لهم من ربنا عن الطريق الرسل أو أي طريقة احنا منعرفهاش.. وكفروا.. فجزاؤهم النار..\n◇ طيب إزاي احنا مش قادرين نعرف مكانهم ونشوفهم وسط التقدم إللي إحنا فيه ده، ووسط بلوغ الإنسان لمشارق الأرض ومغاربها بالشكل ده\nعادي جدا.. ماهو رسول الله ﷺ لما اختبأ من المشركين في غار حراء، وكان المشركين واقفين على باب الغار، \nلو الواحد فيهم بص تحت رجله بس كده كانوا هيشوفوه هو وأبو بكر! يعني همّ وصلوا لحد الغار بالفعل ومفيش واحد منهم كلّف نفسه إنه يبص جوة الغار.. ليه؟\nدي بتاعة ربنا بقى\nوكذلك الحال بالنسبة لمكان يأجوج ومأجوج.. الله أعلم همّ فين، ووقت ما هيأذن هينشكف أمرهم ومكانهم..\nفممكن واحد يقعد كده على جوجل إيرث google earth ومش وراه غير إنه يبحث عن يأجوج ومأجوج في كل شبر من الكرة الأرضية، \nوبعد كم سنة يطلع ويقول والله دول مش موجودين...هل نصدقه إنهم مش موجودين\nطبعا لأ... لإن مين قال لك إن ربنا لم يُعمِ بصرك عن إنك تشوفهم، زي ما ربنا أعمى المشركين إنهم يشوفوا رسول الله ﷺ وهو مُختبئ في غار حراء؟ \nوعارفين كمان زي إيه\nزي ما بني إسرائيل تاهوا في الأرض أربعين سنة في أرض سيناء لما رفضوا دخول الأرض المقدسة\nمكانوش بيقابلوا حد.. وإلا لو كانوا قابلوا حد كان دلّهم على طريق الخروج أو على الأقل الطريق إللي هو جه منه عندهم، فاحنا بنتعامل مع ربنا يا جماعة \nوبعيد عن كل ده: مين قال إنهم فوق الأرض \n مش يمكن تحت الأرض\nرسول الله ﷺ بيقول إيه؟\nبيقول إن كل يوم يأجوج ومأجوج بيحفُروا في السد عشان يخرجوا، وأول ما بس يدخل لهم شعاع الشمس، القائد بتاعهم هيقول لهم بكرة نكمل ..\nويرجعوا تاني يوم يلاقوا الفتحة اتسدت والسد بقى أقوى من الأول، ويفضلوا يحفروا كل يوم وتتسد الحفرة وهكذا...\nلحد ما ييجي اليوم إللي ربنا مقدر فيه إن يأجوج ومأجوج يخرجوا فيه، فالقائد بتاعهم هيقول زي ما بييقول كل يوم : \"نكمل بكرة\" لكن في اليوم ده هيزود كلمة 《إن شاء الله》 فلما هيرجعوا تاني يوم هيلاقوا الحفرة إللي حفروها زي ما كانت، فهيكملوا حفر فيها وبعدين يخرجوا منها بقى على الناس\nالشاهد من الكلام هو جملة:\n\"أول ما يشوفوا شعاع الشمس\" معنى كده إن شعاع الشمس مش واصل لهم أساسا\n \nفيا إما ذو القرنين حبسهم تحت الأرض، يا إما حبسهم في تجويف فوق الأرض محدش شايفه بحول الله وقوته.\nطبعا يا جماعة بعد ما ذو القرنين قفل السد على يأجوج ومأجوج مشي من عندهم وكمل رحلته،\nراح فين بعد كده.؟ .الله أعلم..طب عاش كم سنة؟.. الله أعلم\nزي ما قلنا قبل كده: ربنا بيقولنا إللي يهمنا من القصص عشان ناخد منها العبرة ونطبقها في حياتنا\n☆طب ثواني كده\nمش ذو القرنين حاكم عادل؟ إزاي يحبس ناس ويعرضهم للهلاك وخصوصا إنهم بيخلفوا كتير وأكيد هيتخنقوا كده\nوأصلا ناس بالعدد ده الأكل بيكفيهم إزاي وإزاي عايشين السنين دي كلها محبوسين ؟!\nوهيخرجوا إمتى...وهيخرجوا على مين..هل على المسلمين بس ولّا على كل البشر\nناخدهم واحدة واحدة\n \n◇ لما ذو القرنين حبس يأجوج ومأجوج كان بقدر الله، \nيعني ربنا لما بيقدر على الإنسان حاجة بيخليه يتكيف مع إللي حصل له ده\nمثلا ..في البلاد الحارة عند خط الإستواء هتلاقي البشر بشرتهم سمراء وشعرهم مجعد لهم أكل معين،\nغير البشر إللي في أوروبا ..بشرتهم بيضاء ..شعرهم ناعم وأكلهم مختلف،\nفربنا لما قدّر على يأجوج ومأجوج إنهم يتحبسوا وراء السد أعطاهم القدرة إنهم يتكيفوا مع بيئتهم،\nده غير إننا مانعرفش أصلا إيه هي طبيعة أكل يأجوج ومأجوج...هل بياكلوا اللحوم ولا بياكلوا إيه بالضبط\nلأننا معندناش أي دليل يقول لنا طبيعة الأكل إللي يأجوج ومأجوج عايشين عليه السنين دي كووولها ،\nويمكن يكون عندهم موارد للغذاء من الناحية الثانية من السد،؟\nالاحتمالات لتدبير الله لأمرهم كتيرة\nفهو منعهم وفي نفس الوقت قدر لهم الرزق..إزاااي ..دي بتاعة ربنا مش بتاعتنا \n◇طيب هيخرجوا إمتى...؟ \nخروج يأجوج من علامات الساعة الكبرى ، العلامات المتأخرة إللي مش هتبدأ أصلا إلا بعد ما العلامات الصغرى تكون خلصت وكمان بعض العلامات الكبرى تكون حصلت، \nيعني ماينفعش حد كده يطلع دلوقتي يقول ده يأجوج ومأجوج طلعوا يا جماعة خلاص وهمّ شعب الدولة الفلانية مثلا، \nولا ينفع يقول دول هيطلعوا كمان سنة ولّا سنتين\nإللي يقول كده قولوا له:\n يأجوج ومأجوج مش هيخرجوا غير بعد ما تحصل الملحمة الكبرى والدابة إللي هتخرج تُكلم الناس ويخرج المسيح الدجال في الناس وتحصل الفتنة، وينزل عيسى بن مريم عليه السلام ويقتل المسيح الدجال، \nهنا بقى ربنا هيُوحي لعيسى بن مريم إن فيه بشر خرجوا من حبسهم محدش يقدر عليهم \n..\nفعيسى بن مريم هياخد المؤمنين إللي معاه ويروحوا جبل الطور عشان يحموا نفسهم جواه من يأجوج ومأجوج ،\nلحد ما ربنا يرسل على يأجوج ومأجوج دود معين اسمه \"النّغف\"، هيسلطه على رقابهم، هو إللي هيقتلهم ، \nوالجثث بتاعتهم هتملى الأرض بشكل رهيب لإن عددهم كبير جدا، \nفعيسى عليه السلام هيدعي ربنا إنه يخلص الأرض منهم ومن نتن ريحتهم، فربنا هيرسل طيور تشيل جثث يأجوج ومأجوج وترميهم في المكان إللي ربنا يريده.. \nوبعد كده يُنزل ربنا المطر فيغسل الأرض، \nويَنزل عيسى عليه السلام والمؤمنين من جبل الطور ويعيشوا حتى يقبض الله أرواحهم جميعا\n..\nفالشاهد في كلامنا إن خروج يأجوج ومأجوج محصلش ولا حد يعرف هيحصل إمتى.. \n☆وبالنسبة لعلامات الساعة ان شاءالله هتلاقوها مشروحة في سلسلة السيرة النبوية بالتفصيل من الجزء ال١١٤ لحد الجزء ال١٣٠ لما اخلص قصص الأنبياء \n◇طب هيخرجوا على مين..؟ على المسلمين بس ولّا على كل البشر؟\nالموضوع ده فيه قولين:\n◇القول الأول: إن فساد يأجوج ومأجوج عام لكل البشر. ◇القول الثاني:\nإنه خاص بالعرب والمسلمين، وباقي الأرض بطبيعة الحال هتتأثر ساعتها بخروجهم..\nفهمّ رأيين، واحنا مانقدرش نُجزم ونقول والله ده فتنة يأجوج ومأجوج للبشر كلهم، أو فتنهم للمسلمين فقط،\nلكن أنا شخصيا بميل للرأي التاني أكثر،\nليه\nرسول الله ﷺ دخل مرة وهو مفزوع على زوجته زينب بنت جحش رضي الله عنها وهو بيقول :\n\"لا إله إلا الله، ويل للعرب من شر قد اقترب،\n\"فُتِح من رَدم يأجوج ومأجوج مثل هذه\n\" وأشار بأصابعه علامة كإنه بيوريها حجم الفتحة إللي اتفحت في جدار يأجوج ومأجوج..\nفرسول الله ﷺ ذكر العرب باللفظ في الحديث؛\nلأن الفتنة هتكون فيهم أكثر لإنهم أول من أسلم ومعظم المسلمين هيكونوا فيهم،\nوكمان لما هيخرجوا هيشربوا بحيرة طبرية زي ما قلنا من شوية \nوالكلام ده مذكور في حديث رسول الله ﷺ نفسه،  وبحيرة طبرية مكانها بلاد الشام..\nده غير إن لما يموت عيسى عليه السلام ومعاه المؤمنين، هيتبقى في الأرض شرار الناس... \nفده يدل على إن يأجوج ومأجوج مع كثرتهم لم ينتشروا في الأرض كلها وما أهلكوش كل سكانها، بل كان تأثيرهم الرئيسي في بلاد المسلمين، والله أعلم..\nلكن زي ما قلنا منقدرش نجزم بالموضوع لأن كل فريق له أدلته\n☆إيه الحكمة بقى إن ربنا يقول لنا على قصة يأجوج ومأجوج واحنا إحتمال كبير مانلقحش نحضر خروجهم أصلا\n◇أولا : إحنا عارفين إن المؤمن هو إللي هيدخل الجنة... صح؟ \n طيب من أركان الإيمان إيه\n الإيمان بالغيب... \nويأجوج ومأجوج من الغيبيات،\nفربنا بيقول لنا عن حاجات لو قِسناها بالعقل ماتركبش\n فهنا يبان صدق الإيمان بالغيب \n◇ثانيا: \nربنا بيقول لنا إن يأجوج ومأجوج دول فتنة.. \nوذو القرنين عشان يمنع فتنتهم وشرهم عن الناس خلى فيه بينهم سد..\nفكإن ربنا عز وجل بيقول لنا :\nخلوا بينكم وبين الفتن سد وسدوا الثغرات\nيعني عارف مثلا إنك لو قعدت لوحدك هتعصي ربنا...؟ يبقى هنا تحط سد ومتقعدش لوحدك\nعارفة إنك لو خرجتي مع أصحابك الغير ملتزمات هتعصي ربنا...؟ يبقى تحطي سد ومتخرجيش معاهم... محدش هينفعك في الآخرة\nعارفة إنك ضعيفة أمام الرجال ولو بصيتي لرجل قلبك بينشغل به...؟ حطي سد وغضي بصرك وامنعي الفرجة على صور وأفلام ومقاطع فيها رجال\nعارف إنك لما بتاكل كتير وبتملى بطنك بتكسل عن العبادة..؟ حط سد واعمل حاجز وقاية وقلل أكلك بنية عدم التكاسل عن الطاعة، زي ما رسول الله ﷺ قال: بحسب ابن آدم لقيمات يُقِمن صُلبه\nحطوا سد بينكم وبين الفتن... ابعدوا عنها بكل طريقة.. حتى لو الأمر حلال، قلل منه شوية واغرف منه بحرص وحساب وتدقيق،\nواحد من التابعين كان بيقول: إني لأترك المباح مخافةَ أن أقع في الحرام\nعارفين زي إيه؟\nزي مثلا لما أروح أقعد في كافيه أو مطعم، أهي حاجة مباحة أهه والمكان مافيهوش حاجة غلط على حسب ما هو ظاهر في البداية،\nوبعدين واحنا قاعدين حصل إن في أغاني اشتغلت في المكان وفتحوا شاشة شغلوا عليها أفلام، \nيا ترى هعمل  إيه دلوقتي؟ أنا حاليا في وضع حرام مبقاش مباح، وواجب عليَّ إنكار المنكر بإللي أقدر عليه.. \nوإللي أقدر عليه هنا هو إني أسيب المباح وأمشي لإنه مبقاش مباح، ووقعني في الحرام من  غير ما أقصد... \nطيب بس أنا طلبت خلاص أكل وشرب مش هينفع أمشي! كده يبقى أنا وقعت في حرج وفتنة كان بدايتها عدم الاغتراف من المباح بحساب وبوعي واحتراز\nأي حاجة مباحة وحلال هتلاقيها ممكن توقعك في الحرام مهما كان درجته، وتبقى مش قادر ساعتها ترفعه، سيبه لله وحط بينك وبين الحاجة دي سد\n.. ومن ترك شيـئا لله عوضه خيرا منه.\nوالجنة تستاهل، ومحدش عارف هيموت إمتى وفين وعلى أنهي حال أو نية..\nوخصوصا إننا كل شوية نسمع عن شباب كثير انتهى عمرهم بموت الفجأة\nربنا يرحم أموات المسلمين أجمعين، ويرحمنا ويعصمنا جميعا من الفتن ما ظهر منها وما بَطن ..آمين يارب\nإن شاء الله من أول المرة الجاية هنتكلم عن بعض القصص إللي حصلت في أزمنة الأنبياء، \nلكن عشان هي مش معروف وقتها إيه بالضبط فهنحكيهم قبل ما ندخل في قصة زكريا عليه السلام\n♡معلش طولت عليكم أوي المرة دي"}]);
